/* Blackboard lessons for the derivatives cheat sheet: one lesson per row of the two derivative tables.
   Each lesson: the rule (f and f′ on the graph), the chain-rule column with a worked example, an exam-style exercise.
   Keys: 'Table of derivatives/<the row's f(x) cell>' (see js/tutor.js). Texts: 'en|fr|es|ja|zh'. */
(function () {
  const R = String.raw;
  const RULE = 'The rule|La règle|La regla|公式|公式';
  const CHAIN = 'With the chain rule|Avec la dérivation en chaîne|Con la regla de la cadena|合成関数の微分|结合链式法则';
  const YOUR = 'Your turn|À vous|Te toca|やってみよう|轮到你了';
  const TRY = R`Differentiate on paper (or on the board), type $f'(x)$ and check it. Stuck? Each hint writes the next line of the solution.|Dérivez sur papier (ou au tableau), tapez $f'(x)$ et vérifiez. Bloqué ? Chaque indice écrit la ligne suivante de la solution.|Deriva en papel (o en la pizarra), escribe $f'(x)$ y compruébalo. ¿Atascado? Cada pista escribe la siguiente línea de la solución.|紙（または黒板）で微分し、$f'(x)$ を入力して確かめましょう。行き詰まったら、ヒントごとに解答の次の行が書かれます。|在纸上（或黑板上）求导，输入 $f'(x)$ 并检查。卡住了？每个提示会写出解答的下一行。`;
  const LEG = R`Yellow: $f$. Blue: $f'$ — its height is the slope of the yellow curve.|Jaune : $f$. Bleu : $f'$ — sa hauteur est la pente de la courbe jaune.|Amarillo: $f$. Azul: $f'$ — su altura es la pendiente de la curva amarilla.|黄：$f$、青：$f'$。青の高さが黄色の曲線の傾きです。|黄色：$f$，蓝色：$f'$——它的高度就是黄色曲线的斜率。`;

  const F = (tex, o = {}) => ['w', R`\displaystyle ` + tex, Object.assign({ s: 28 }, o)];
  const Y = (tex, o = {}) => F(tex, Object.assign({ c: 'y' }, o));
  const head = (tex) => ['w', tex, { head: true, s: 18, c: 'y' }];
  const graph = (fa, fpa, xw, yw, extra = []) => [['ax', { xw, yw }], ['p', 'y=' + fa, { c: 'y' }], ['p', 'y=' + fpa, { c: '#93d3f5', d: 400 }], ...extra];

  // row: f, f′ and the chain-rule column (as in cheats/derivatives.js), plot formulas, texts, example, exercise
  const ROWS = [
    { f: R`c`, fp: R`0`, fu: R`0`, fa: '3', fpa: '0', xw: [-3, 3], yw: [-1, 4],
      s: R`A constant never changes, so its graph is a flat line and its slope is 0 everywhere. Constants added to a function disappear when you differentiate; constants multiplying it stay.|Une constante ne varie pas : son graphe est une droite horizontale, de pente nulle partout. Une constante ajoutée disparaît en dérivant ; une constante en facteur reste.|Una constante no cambia: su gráfica es una recta horizontal y su pendiente es 0 en todas partes. Una constante sumada desaparece al derivar; una que multiplica se queda.|定数は変化しないので、グラフは水平な直線で傾きはどこでも 0。足された定数は微分で消え、掛けられた定数は残ります。|常数不变，图像是水平直线，斜率处处为 0。加上的常数求导后消失，乘上的常数保留。`,
      cs: R`Even when the constant is a big expression like $\pi^2$ or $\ln 5$, its derivative is 0 — but $(5x)' = 5$ because there $x$ is moving.|Même si la constante est une grosse expression comme $\pi^2$ ou $\ln 5$, sa dérivée vaut 0 — mais $(5x)' = 5$ car là $x$ varie.|Aunque la constante sea una expresión grande como $\pi^2$ o $\ln 5$, su derivada es 0; pero $(5x)' = 5$ porque ahí $x$ se mueve.|$\pi^2$ や $\ln 5$ のような式でも定数なら微分は 0。ただし $(5x)' = 5$（$x$ が動くから）。|即使常数是 $\pi^2$、$\ln 5$ 这样的式子，导数也是 0——但 $(5x)' = 5$，因为其中 $x$ 在变。`,
      eg: [R`(\pi^2 + \ln 5)' = 0`, R`(5x + 7)' = 5 + 0 = 5`], ega: '5x+7', egpa: '5', egx: [-2, 2], egy: [-4, 18],
      ex: { q: R`f(x) = x^2 + 9`, f: 'x^2+9', sol: [R`(x^2)' = 2x,\quad (9)' = 0`, R`f'(x) = 2x`] } },
    { f: R`x^n`, fp: R`n\,x^{n-1}`, fu: R`n\,u^{n-1}\,u'`, fa: 'x^3', fpa: '3x^2', xw: [-1.8, 1.8], yw: [-3, 6],
      s: R`Bring the exponent down in front, then lower it by one. It works for any real $n$: $(x^3)' = 3x^2$, $(x^{-1})' = -x^{-2}$, $(x^{1/2})' = \tfrac12 x^{-1/2}$.|On descend l’exposant devant, puis on le diminue de 1. Valable pour tout réel $n$ : $(x^3)' = 3x^2$, $(x^{-1})' = -x^{-2}$, $(x^{1/2})' = \tfrac12 x^{-1/2}$.|Baja el exponente delante y réstale uno. Vale para cualquier $n$ real: $(x^3)' = 3x^2$, $(x^{-1})' = -x^{-2}$, $(x^{1/2})' = \tfrac12 x^{-1/2}$.|指数を前に下ろし、指数を 1 減らします。任意の実数 $n$ で成立：$(x^3)' = 3x^2$、$(x^{-1})' = -x^{-2}$、$(x^{1/2})' = \tfrac12 x^{-1/2}$。|把指数拿到前面，再把指数减 1。对任意实数 $n$ 成立：$(x^3)' = 3x^2$，$(x^{-1})' = -x^{-2}$，$(x^{1/2})' = \tfrac12 x^{-1/2}$。`,
      cs: R`If the base is a whole expression $u$, do the same and then multiply by the derivative of the inside, $u'$.|Si la base est une expression $u$, on fait pareil puis on multiplie par la dérivée de l’intérieur, $u'$.|Si la base es una expresión $u$, haz lo mismo y multiplica por la derivada del interior, $u'$.|底が式 $u$ なら同じようにして、最後に中身の微分 $u'$ を掛けます。|若底数是表达式 $u$，同样处理后再乘以内层的导数 $u'$。`,
      eg: [R`\big((x^2 + 1)^3\big)' = 3(x^2 + 1)^2\cdot 2x`, R`= 6x(x^2 + 1)^2`], ega: '(x^2+1)^3', egpa: '6x*(x^2+1)^2', egx: [-1.3, 1.3], egy: [-12, 16],
      ex: { q: R`f(x) = (2x - 1)^5`, f: '(2x-1)^5', sol: [R`u = 2x - 1,\ u' = 2`, R`f'(x) = 5(2x - 1)^4\cdot 2 = 10(2x - 1)^4`] } },
    { f: R`\sqrt x`, fp: R`\frac{1}{2\sqrt x}`, fu: R`\frac{u'}{2\sqrt u}`, fa: 'sqrt(x)', fpa: '1/(2sqrt(x))', xw: [-0.4, 4], yw: [-0.3, 2.4],
      s: R`$\sqrt x = x^{1/2}$, so the power rule gives $\tfrac12 x^{-1/2}$. The slope is huge near 0 (the curve starts vertical) and shrinks as $x$ grows.|$\sqrt x = x^{1/2}$ : la règle des puissances donne $\tfrac12 x^{-1/2}$. La pente est énorme près de 0 (la courbe part verticale) et diminue quand $x$ grandit.|$\sqrt x = x^{1/2}$, así que la regla de la potencia da $\tfrac12 x^{-1/2}$. La pendiente es enorme cerca de 0 (la curva sale vertical) y se reduce al crecer $x$.|$\sqrt x = x^{1/2}$ なので累乗の公式から $\tfrac12 x^{-1/2}$。0 の近くでは傾きが非常に大きく（曲線は垂直に出発）、$x$ が大きくなると小さくなります。|$\sqrt x = x^{1/2}$，由幂法则得 $\tfrac12 x^{-1/2}$。在 0 附近斜率极大（曲线竖直出发），随 $x$ 增大而变小。`,
      cs: R`For a root of an expression, the derivative of the inside goes on top: $\big(\sqrt{u}\big)' = \tfrac{u'}{2\sqrt u}$.|Pour la racine d’une expression, la dérivée de l’intérieur passe au numérateur : $\big(\sqrt{u}\big)' = \tfrac{u'}{2\sqrt u}$.|Para la raíz de una expresión, la derivada del interior va arriba: $\big(\sqrt{u}\big)' = \tfrac{u'}{2\sqrt u}$.|式の平方根では、中身の微分が分子に来ます：$\big(\sqrt{u}\big)' = \tfrac{u'}{2\sqrt u}$。|对表达式开根号，内层导数放在分子：$\big(\sqrt{u}\big)' = \tfrac{u'}{2\sqrt u}$。`,
      eg: [R`\big(\sqrt{x^2 + 1}\big)' = \frac{2x}{2\sqrt{x^2 + 1}}`, R`= \frac{x}{\sqrt{x^2 + 1}}`], ega: 'sqrt(x^2+1)', egpa: 'x/sqrt(x^2+1)', egx: [-3, 3], egy: [-1.4, 3.4],
      ex: { q: R`f(x) = \sqrt{3x + 1}`, f: 'sqrt(3x+1)', sol: [R`u = 3x + 1,\ u' = 3`, R`f'(x) = \frac{3}{2\sqrt{3x + 1}}`] } },
    { f: R`\sqrt[n]{x}`, fp: R`\frac{1}{n\sqrt[n]{x^{n-1}}}`, fu: R`\frac{u'}{n\sqrt[n]{u^{n-1}}}`, fa: 'x^(1/3)', fpa: '1/(3x^(2/3))', xw: [-0.4, 5], yw: [-0.3, 2.2],
      s: R`Write the root as a power, $\sqrt[n]{x} = x^{1/n}$, and use the power rule: $\tfrac1n x^{\frac1n - 1}$. Shown here for the cube root ($n = 3$).|Écrivez la racine comme une puissance, $\sqrt[n]{x} = x^{1/n}$, puis appliquez la règle des puissances : $\tfrac1n x^{\frac1n - 1}$. Ici la racine cubique ($n = 3$).|Escribe la raíz como potencia, $\sqrt[n]{x} = x^{1/n}$, y usa la regla de la potencia: $\tfrac1n x^{\frac1n - 1}$. Aquí, la raíz cúbica ($n = 3$).|根号を累乗に直し $\sqrt[n]{x} = x^{1/n}$、累乗の公式で $\tfrac1n x^{\frac1n - 1}$。図は立方根（$n = 3$）。|把根式写成幂 $\sqrt[n]{x} = x^{1/n}$，用幂法则得 $\tfrac1n x^{\frac1n - 1}$。图中为立方根（$n = 3$）。`,
      cs: R`The same with an expression inside: convert to a power, bring it down, multiply by $u'$.|De même avec une expression à l’intérieur : on passe en puissance, on descend l’exposant, on multiplie par $u'$.|Igual con una expresión dentro: pasa a potencia, baja el exponente y multiplica por $u'$.|中が式でも同じ：累乗に直して指数を下ろし、$u'$ を掛けます。|内层是表达式时一样：化成幂，指数提前，再乘 $u'$。`,
      eg: [R`\big(\sqrt[3]{x^2}\big)' = \big(x^{2/3}\big)' = \tfrac23\,x^{-1/3}`, R`= \frac{2}{3\sqrt[3]{x}}`], ega: 'x^(2/3)', egpa: '2/(3x^(1/3))', egx: [-0.3, 4], egy: [-0.3, 3],
      ex: { q: R`f(x) = \sqrt[3]{x + 8}`, f: '(x+8)^(1/3)', sol: [R`= (x + 8)^{1/3}`, R`f'(x) = \tfrac13 (x + 8)^{-2/3} = \frac{1}{3\sqrt[3]{(x + 8)^2}}`] } },
    { f: R`\frac1x`, fp: R`-\frac{1}{x^2}`, fu: R`-\frac{u'}{u^2}`, fa: '1/x', fpa: '-1/x^2', xw: [-3, 3], yw: [-4, 4],
      s: R`$\tfrac1x = x^{-1}$, so the derivative is $-x^{-2} = -\tfrac{1}{x^2}$. It is negative everywhere: the hyperbola always goes down, on both sides of 0.|$\tfrac1x = x^{-1}$, donc la dérivée est $-x^{-2} = -\tfrac{1}{x^2}$. Elle est négative partout : l’hyperbole descend toujours, des deux côtés de 0.|$\tfrac1x = x^{-1}$, así que la derivada es $-x^{-2} = -\tfrac{1}{x^2}$. Es negativa en todas partes: la hipérbola siempre baja, a ambos lados de 0.|$\tfrac1x = x^{-1}$ なので導関数は $-x^{-2} = -\tfrac{1}{x^2}$。どこでも負で、双曲線は 0 の両側で常に減少します。|$\tfrac1x = x^{-1}$，导数为 $-x^{-2} = -\tfrac{1}{x^2}$。处处为负：双曲线在 0 两侧都一直下降。`,
      cs: R`For one over an expression: minus the derivative of the bottom, over the bottom squared.|Pour l’inverse d’une expression : moins la dérivée du dénominateur, sur le dénominateur au carré.|Para uno entre una expresión: menos la derivada del denominador, entre el denominador al cuadrado.|式の逆数は「分母の微分にマイナスを付け、分母の 2 乗で割る」。|表达式的倒数：负的分母导数，除以分母的平方。`,
      eg: [R`\Big(\frac{1}{x^2 + 1}\Big)' = -\frac{2x}{(x^2 + 1)^2}`], ega: '1/(x^2+1)', egpa: '-2x/(x^2+1)^2', egx: [-3, 3], egy: [-0.9, 1.3],
      ex: { q: R`f(x) = \frac{1}{3x - 2}`, f: '1/(3x-2)', sol: [R`u = 3x - 2,\ u' = 3`, R`f'(x) = -\frac{3}{(3x - 2)^2}`] } },
    { f: R`e^x`, fp: R`e^x`, fu: R`e^u\,u'`, fa: 'e^x', fpa: 'e^x', xw: [-3, 2], yw: [-0.5, 6],
      s: R`$e^x$ is the function that is its own derivative: at every point its slope equals its height. That is why the two curves on the board are the same.|$e^x$ est sa propre dérivée : en chaque point sa pente vaut sa hauteur. C’est pourquoi les deux courbes du tableau sont confondues.|$e^x$ es su propia derivada: en cada punto su pendiente es igual a su altura. Por eso las dos curvas de la pizarra coinciden.|$e^x$ は自分自身が導関数：各点で傾きが高さと等しい。だから黒板の 2 本の曲線は重なります。|$e^x$ 的导数就是它自己：每一点的斜率等于高度，所以黑板上两条曲线重合。`,
      cs: R`With an exponent that is an expression, copy $e^u$ and multiply by the derivative of the exponent.|Si l’exposant est une expression, on recopie $e^u$ et on multiplie par la dérivée de l’exposant.|Si el exponente es una expresión, copia $e^u$ y multiplica por la derivada del exponente.|指数が式なら、$e^u$ をそのまま書いて指数の微分を掛けます。|指数是表达式时，照抄 $e^u$，再乘以指数的导数。`,
      eg: [R`\big(e^{x^2}\big)' = e^{x^2}\cdot 2x`], ega: 'e^(x^2)', egpa: '2x*e^(x^2)', egx: [-1.4, 1.4], egy: [-8, 8],
      ex: { q: R`f(x) = e^{-3x}`, f: 'e^(-3x)', sol: [R`u = -3x,\ u' = -3`, R`f'(x) = -3e^{-3x}`] } },
    { f: R`a^x`, fp: R`a^x\ln a`, fu: R`a^u\ln a\cdot u'`, fa: '2^x', fpa: '2^x*ln(2)', xw: [-3, 2.5], yw: [-0.5, 6],
      s: R`Write $a^x = e^{x\ln a}$: the chain rule brings out the constant $\ln a$. For $a = 2$ the slope is about $0.69$ times the height; only for $a = e$ is the factor 1.|On écrit $a^x = e^{x\ln a}$ : la dérivation en chaîne fait sortir la constante $\ln a$. Pour $a = 2$, la pente vaut environ $0{,}69$ fois la hauteur ; le facteur n’est 1 que pour $a = e$.|Escribe $a^x = e^{x\ln a}$: la regla de la cadena saca la constante $\ln a$. Para $a = 2$ la pendiente es unas $0{,}69$ veces la altura; solo para $a = e$ el factor es 1.|$a^x = e^{x\ln a}$ と書くと、合成関数の微分で定数 $\ln a$ が出ます。$a = 2$ なら傾きは高さの約 $0.69$ 倍。係数が 1 になるのは $a = e$ のときだけ。|写成 $a^x = e^{x\ln a}$，链式法则带出常数 $\ln a$。$a = 2$ 时斜率约为高度的 $0.69$ 倍；只有 $a = e$ 时系数为 1。`,
      cs: R`With an expression in the exponent: copy $a^u$, multiply by $\ln a$ and by $u'$.|Avec une expression en exposant : on recopie $a^u$, on multiplie par $\ln a$ et par $u'$.|Con una expresión en el exponente: copia $a^u$ y multiplica por $\ln a$ y por $u'$.|指数が式なら：$a^u$ をそのまま書き、$\ln a$ と $u'$ を掛けます。|指数是表达式时：照抄 $a^u$，乘以 $\ln a$ 和 $u'$。`,
      eg: [R`\big(3^{2x}\big)' = 3^{2x}\ln 3\cdot 2`, R`= 2\ln 3\cdot 3^{2x}`], ega: '3^(2x)', egpa: '2ln(3)*3^(2x)', egx: [-1.5, 0.8], egy: [-0.5, 10],
      ex: { q: R`f(x) = 5^{x^2}`, f: '5^(x^2)', sol: [R`u = x^2,\ u' = 2x`, R`f'(x) = 5^{x^2}\ln 5\cdot 2x`] } },
    { f: R`\ln x`, fp: R`\frac1x`, fu: R`\frac{u'}{u}`, fa: 'ln(x)', fpa: '1/x', xw: [-0.4, 5], yw: [-2.5, 3],
      s: R`The logarithm grows more and more slowly: its slope at $x$ is exactly $\tfrac1x$ — steep near 0, almost flat far away. It only exists for $x > 0$.|Le logarithme croît de plus en plus lentement : sa pente en $x$ vaut exactement $\tfrac1x$ — raide près de 0, presque plate au loin. Il n’existe que pour $x > 0$.|El logaritmo crece cada vez más despacio: su pendiente en $x$ es exactamente $\tfrac1x$, empinada cerca de 0 y casi plana lejos. Solo existe para $x > 0$.|対数はだんだんゆっくり増えます。$x$ での傾きはちょうど $\tfrac1x$：0 付近では急、遠くではほぼ平ら。定義域は $x > 0$。|对数增长越来越慢：在 $x$ 处的斜率恰为 $\tfrac1x$——在 0 附近陡，远处几乎平。只在 $x > 0$ 时有定义。`,
      cs: R`The log of an expression: derivative of the inside over the inside. This is the “logarithmic derivative”.|Le logarithme d’une expression : dérivée de l’intérieur sur l’intérieur. C’est la « dérivée logarithmique ».|El logaritmo de una expresión: derivada del interior entre el interior. Es la «derivada logarítmica».|式の対数は「中身の微分 ÷ 中身」。これが対数微分です。|表达式的对数：内层导数除以内层。这就是“对数导数”。`,
      eg: [R`\big(\ln(x^2 + 1)\big)' = \frac{2x}{x^2 + 1}`], ega: 'ln(x^2+1)', egpa: '2x/(x^2+1)', egx: [-3, 3], egy: [-1.3, 2.4],
      ex: { q: R`f(x) = \ln(x^2 + 3x)\quad (x > 0)`, f: 'ln(x^2+3x)', sol: [R`u = x^2 + 3x,\ u' = 2x + 3`, R`f'(x) = \frac{2x + 3}{x^2 + 3x}`] } },
    { f: R`\log_a x`, fp: R`\frac{1}{x\ln a}`, fu: R`\frac{u'}{u\ln a}`, fa: 'ln(x)/ln(2)', fpa: '1/(x*ln(2))', xw: [-0.4, 5], yw: [-3, 3.2],
      s: R`Change the base first: $\log_a x = \tfrac{\ln x}{\ln a}$. Since $\ln a$ is just a number, the derivative is $\tfrac{1}{x\ln a}$. Shown for $\log_2$.|On change de base : $\log_a x = \tfrac{\ln x}{\ln a}$. Comme $\ln a$ est un simple nombre, la dérivée vaut $\tfrac{1}{x\ln a}$. Ici $\log_2$.|Cambia primero de base: $\log_a x = \tfrac{\ln x}{\ln a}$. Como $\ln a$ es solo un número, la derivada es $\tfrac{1}{x\ln a}$. Aquí, $\log_2$.|まず底の変換：$\log_a x = \tfrac{\ln x}{\ln a}$。$\ln a$ はただの数なので導関数は $\tfrac{1}{x\ln a}$。図は $\log_2$。|先换底：$\log_a x = \tfrac{\ln x}{\ln a}$。$\ln a$ 只是一个数，所以导数为 $\tfrac{1}{x\ln a}$。图为 $\log_2$。`,
      cs: R`With an expression inside: as for $\ln u$, then divide by $\ln a$.|Avec une expression à l’intérieur : comme pour $\ln u$, puis on divise par $\ln a$.|Con una expresión dentro: como con $\ln u$ y luego divide entre $\ln a$.|中が式なら：$\ln u$ と同じようにして $\ln a$ で割ります。|内层是表达式：与 $\ln u$ 相同，再除以 $\ln a$。`,
      eg: [R`\big(\log_{10}(x^2)\big)' = \frac{2x}{x^2\ln 10}`, R`= \frac{2}{x\ln 10}`], ega: 'ln(x^2)/ln(10)', egpa: '2/(x*ln(10))', egx: [-0.3, 5], egy: [-2, 2.5],
      ex: { q: R`f(x) = \log_2(3x + 1)`, f: 'ln(3x+1)/ln(2)', sol: [R`u = 3x + 1,\ u' = 3`, R`f'(x) = \frac{3}{(3x + 1)\ln 2}`] } },
    { f: R`\sinh x`, fp: R`\cosh x`, fu: R`\cosh u\cdot u'`, fa: '(e^x-e^(-x))/2', fpa: '(e^x+e^(-x))/2', xw: [-2.6, 2.6], yw: [-4, 4],
      s: R`$\sinh x = \tfrac{e^x - e^{-x}}{2}$. Differentiating each exponential turns the minus into a plus, which is exactly $\cosh x$. No minus sign appears (unlike $\sin$ and $\cos$).|$\sinh x = \tfrac{e^x - e^{-x}}{2}$. En dérivant chaque exponentielle, le moins devient un plus : c’est exactement $\cosh x$. Pas de signe moins (contrairement à $\sin$ et $\cos$).|$\sinh x = \tfrac{e^x - e^{-x}}{2}$. Al derivar cada exponencial el menos se vuelve más: es justo $\cosh x$. No aparece ningún signo menos (a diferencia de $\sin$ y $\cos$).|$\sinh x = \tfrac{e^x - e^{-x}}{2}$。各指数関数を微分するとマイナスがプラスになり、ちょうど $\cosh x$。（$\sin$・$\cos$ と違い）マイナスは出ません。|$\sinh x = \tfrac{e^x - e^{-x}}{2}$。对每个指数求导，减号变加号，恰好是 $\cosh x$。不出现负号（与 $\sin$、$\cos$ 不同）。`,
      cs: R`With an expression inside: $\cosh u$ times $u'$. Type $\cosh$ as cosh(...) in the exercises.|Avec une expression à l’intérieur : $\cosh u$ fois $u'$. Dans les exercices, tapez $\cosh$ sous la forme cosh(...).|Con una expresión dentro: $\cosh u$ por $u'$. En los ejercicios escribe $\cosh$ como cosh(...).|中が式なら $\cosh u$ に $u'$ を掛けます。演習では $\cosh$ を cosh(...) と入力します。|内层是表达式：$\cosh u$ 乘 $u'$。练习中把 $\cosh$ 输入为 cosh(...)。`,
      eg: [R`(\sinh 2x)' = 2\cosh 2x`], ega: '(e^(2x)-e^(-2x))/2', egpa: 'e^(2x)+e^(-2x)', egx: [-1.4, 1.4], egy: [-8, 9],
      ex: { q: R`f(x) = \sinh(x^2)`, f: '(e^(x^2)-e^(-x^2))/2', sol: [R`u = x^2,\ u' = 2x`, R`f'(x) = 2x\cosh(x^2)`] } },
    { f: R`\cosh x`, fp: R`\sinh x`, fu: R`\sinh u\cdot u'`, fa: '(e^x+e^(-x))/2', fpa: '(e^x-e^(-x))/2', xw: [-2.6, 2.6], yw: [-4, 5],
      s: R`$\cosh x = \tfrac{e^x + e^{-x}}{2}$ is the shape of a hanging chain. Its slope is $\sinh x$: 0 at the bottom, negative on the left, positive on the right.|$\cosh x = \tfrac{e^x + e^{-x}}{2}$ est la forme d’une chaîne suspendue. Sa pente est $\sinh x$ : nulle en bas, négative à gauche, positive à droite.|$\cosh x = \tfrac{e^x + e^{-x}}{2}$ es la forma de una cadena colgante. Su pendiente es $\sinh x$: 0 abajo, negativa a la izquierda y positiva a la derecha.|$\cosh x = \tfrac{e^x + e^{-x}}{2}$ は垂れ下がった鎖の形（懸垂線）。傾きは $\sinh x$：底で 0、左で負、右で正。|$\cosh x = \tfrac{e^x + e^{-x}}{2}$ 是悬链线的形状。斜率为 $\sinh x$：最低点为 0，左侧为负，右侧为正。`,
      cs: R`With an expression inside: $\sinh u$ times $u'$.|Avec une expression à l’intérieur : $\sinh u$ fois $u'$.|Con una expresión dentro: $\sinh u$ por $u'$.|中が式なら $\sinh u$ に $u'$ を掛けます。|内层是表达式：$\sinh u$ 乘 $u'$。`,
      eg: [R`(\cosh 3x)' = 3\sinh 3x`], ega: '(e^(3x)+e^(-3x))/2', egpa: '3(e^(3x)-e^(-3x))/2', egx: [-1, 1], egy: [-9, 9],
      ex: { q: R`f(x) = \cosh(2x)`, f: '(e^(2x)+e^(-2x))/2', sol: [R`u = 2x,\ u' = 2`, R`f'(x) = 2\sinh(2x)`] } },
    { f: R`\sin x`, fp: R`\cos x`, fu: R`\cos u\cdot u'`, fa: 'sin(x)', fpa: 'cos(x)', xw: [-3.5, 6.5], yw: [-1.6, 1.6],
      s: R`Where $\sin x$ climbs fastest (at 0) its slope is 1, which is $\cos 0$; at the top of the wave the slope is 0, which is $\cos\tfrac\pi2$. The slope curve is the cosine.|Là où $\sin x$ monte le plus vite (en 0) sa pente vaut 1, soit $\cos 0$ ; au sommet de la vague la pente est nulle, soit $\cos\tfrac\pi2$. La courbe des pentes est le cosinus.|Donde $\sin x$ sube más rápido (en 0) su pendiente es 1, que es $\cos 0$; en la cima de la onda la pendiente es 0, que es $\cos\tfrac\pi2$. La curva de pendientes es el coseno.|$\sin x$ が最も急に増える 0 で傾きは 1（$= \cos 0$）、波の頂上では傾き 0（$= \cos\tfrac\pi2$）。傾きのグラフが余弦です。|$\sin x$ 上升最快处（0）斜率为 1，即 $\cos 0$；波峰处斜率为 0，即 $\cos\tfrac\pi2$。斜率曲线就是余弦。`,
      cs: R`For the sine of an expression: cosine of the same expression, times the derivative of the inside. Angles must be in radians.|Pour le sinus d’une expression : le cosinus de la même expression, fois la dérivée de l’intérieur. Les angles sont en radians.|Para el seno de una expresión: el coseno de la misma expresión por la derivada del interior. Los ángulos, en radianes.|式の正弦は「同じ式の余弦 × 中身の微分」。角はラジアン。|表达式的正弦：同一表达式的余弦乘以内层导数。角度用弧度。`,
      eg: [R`(\sin 3x)' = 3\cos 3x`], ega: 'sin(3x)', egpa: '3cos(3x)', egx: [-2.2, 2.2], egy: [-3.4, 3.4],
      ex: { q: R`f(x) = \sin(x^2)`, f: 'sin(x^2)', sol: [R`u = x^2,\ u' = 2x`, R`f'(x) = 2x\cos(x^2)`] } },
    { f: R`\cos x`, fp: R`-\sin x`, fu: R`-\sin u\cdot u'`, fa: 'cos(x)', fpa: '-sin(x)', xw: [-3.5, 6.5], yw: [-1.6, 1.6],
      s: R`Just after 0 the cosine starts to fall, so its slope is negative: the derivative is $-\sin x$. Remember the minus sign — it is the most common mistake.|Juste après 0 le cosinus commence à descendre : sa pente est négative, la dérivée est $-\sin x$. Attention au signe moins, c’est l’erreur la plus fréquente.|Justo después de 0 el coseno empieza a bajar, así que su pendiente es negativa: la derivada es $-\sin x$. Ojo con el signo menos: es el error más común.|0 の直後で余弦は下がり始めるので傾きは負：導関数は $-\sin x$。マイナスを忘れるのが最も多い間違いです。|0 之后余弦开始下降，斜率为负：导数是 $-\sin x$。别忘了负号——这是最常见的错误。`,
      cs: R`Cosine of an expression: minus sine of the same expression, times $u'$.|Cosinus d’une expression : moins le sinus de la même expression, fois $u'$.|Coseno de una expresión: menos el seno de la misma expresión, por $u'$.|式の余弦は「−（同じ式の正弦）× $u'$」。|表达式的余弦：负的同一表达式的正弦，乘以 $u'$。`,
      eg: [R`\big(\cos(2x + 1)\big)' = -2\sin(2x + 1)`], ega: 'cos(2x+1)', egpa: '-2sin(2x+1)', egx: [-2.5, 2.5], egy: [-2.3, 2.3],
      ex: { q: R`f(x) = \cos^2 x`, f: 'cos(x)^2', sol: [R`u = \cos x,\ (u^2)' = 2u\,u'`, R`f'(x) = 2\cos x\cdot(-\sin x) = -\sin 2x`] } },
    { f: R`\tan x`, fp: R`\frac{1}{\cos^2 x} = 1 + \tan^2 x`, fu: R`\frac{u'}{\cos^2 u}`, fa: 'tan(x)', fpa: '1/cos(x)^2', xw: [-1.5, 1.5], yw: [-4, 5],
      s: R`From the quotient rule on $\tfrac{\sin x}{\cos x}$. The slope is never below 1 (at 0 it is exactly 1) and it explodes near $\pm\tfrac\pi2$, where the tangent has asymptotes. Both forms are useful.|Par la règle du quotient sur $\tfrac{\sin x}{\cos x}$. La pente n’est jamais inférieure à 1 (en 0 elle vaut 1) et explose près de $\pm\tfrac\pi2$, où la tangente a des asymptotes. Les deux formes servent.|De la regla del cociente aplicada a $\tfrac{\sin x}{\cos x}$. La pendiente nunca baja de 1 (en 0 vale 1) y se dispara cerca de $\pm\tfrac\pi2$, donde la tangente tiene asíntotas. Las dos formas son útiles.|$\tfrac{\sin x}{\cos x}$ に商の微分を使って得られます。傾きは 1 未満にならず（0 でちょうど 1）、漸近線のある $\pm\tfrac\pi2$ 付近で急増します。両方の形が役立ちます。|对 $\tfrac{\sin x}{\cos x}$ 用商法则得到。斜率从不小于 1（在 0 处恰为 1），在有渐近线的 $\pm\tfrac\pi2$ 附近急剧增大。两种形式都有用。`,
      cs: R`Tangent of an expression: $u'$ over cosine squared of the same expression.|Tangente d’une expression : $u'$ sur le cosinus au carré de la même expression.|Tangente de una expresión: $u'$ entre el coseno al cuadrado de la misma expresión.|式の正接は「$u'$ ÷ 同じ式の余弦の 2 乗」。|表达式的正切：$u'$ 除以同一表达式余弦的平方。`,
      eg: [R`\big(\tan x^2\big)' = \frac{2x}{\cos^2(x^2)}`], ega: 'tan(x^2)', egpa: '2x/cos(x^2)^2', egx: [-1.2, 1.2], egy: [-6, 6],
      ex: { q: R`f(x) = \tan(3x)`, f: 'tan(3x)', sol: [R`u = 3x,\ u' = 3`, R`f'(x) = \frac{3}{\cos^2(3x)}`] } },
    { f: R`\cot x`, fp: R`-\frac{1}{\sin^2 x}`, fu: R`-\frac{u'}{\sin^2 u}`, fa: 'cos(x)/sin(x)', fpa: '-1/sin(x)^2', xw: [0.1, 3.05], yw: [-5, 5],
      s: R`$\cot x = \tfrac{\cos x}{\sin x}$ always decreases between its asymptotes, so its derivative $-\tfrac{1}{\sin^2 x}$ is always negative (at most $-1$).|$\cot x = \tfrac{\cos x}{\sin x}$ décroît toujours entre ses asymptotes : sa dérivée $-\tfrac{1}{\sin^2 x}$ est toujours négative (au plus $-1$).|$\cot x = \tfrac{\cos x}{\sin x}$ siempre decrece entre sus asíntotas, así que su derivada $-\tfrac{1}{\sin^2 x}$ es siempre negativa (como mucho $-1$).|$\cot x = \tfrac{\cos x}{\sin x}$ は漸近線の間で常に減少するので、導関数 $-\tfrac{1}{\sin^2 x}$ は常に負（最大でも $-1$）。|$\cot x = \tfrac{\cos x}{\sin x}$ 在渐近线之间一直递减，所以导数 $-\tfrac{1}{\sin^2 x}$ 恒为负（最大为 $-1$）。`,
      cs: R`Cotangent of an expression: minus $u'$ over sine squared. Type it as cot(...).|Cotangente d’une expression : moins $u'$ sur le sinus au carré. Tapez-la cot(...).|Cotangente de una expresión: menos $u'$ entre el seno al cuadrado. Escríbela cot(...).|式の余接は「$-u'$ ÷ 正弦の 2 乗」。cot(...) と入力します。|表达式的余切：负的 $u'$ 除以正弦平方。输入为 cot(...)。`,
      eg: [R`(\cot 2x)' = -\frac{2}{\sin^2 2x}`], ega: 'cos(2x)/sin(2x)', egpa: '-2/sin(2x)^2', egx: [0.05, 1.52], egy: [-8, 8],
      ex: { q: R`f(x) = \cot(x^2)`, f: 'cos(x^2)/sin(x^2)', sol: [R`u = x^2,\ u' = 2x`, R`f'(x) = -\frac{2x}{\sin^2(x^2)}`] } },
    { f: R`\sec x`, fp: R`\sec x\tan x`, fu: R`\sec u\tan u\cdot u'`, fa: '1/cos(x)', fpa: 'sin(x)/cos(x)^2', xw: [-1.5, 1.5], yw: [-4, 5],
      s: R`$\sec x = \tfrac{1}{\cos x}$. The rule for $\tfrac1u$ gives $\tfrac{\sin x}{\cos^2 x} = \sec x\tan x$. The bowl has slope 0 at the bottom ($x = 0$).|$\sec x = \tfrac{1}{\cos x}$. La règle de $\tfrac1u$ donne $\tfrac{\sin x}{\cos^2 x} = \sec x\tan x$. La cuvette a une pente nulle au fond ($x = 0$).|$\sec x = \tfrac{1}{\cos x}$. La regla de $\tfrac1u$ da $\tfrac{\sin x}{\cos^2 x} = \sec x\tan x$. El cuenco tiene pendiente 0 en el fondo ($x = 0$).|$\sec x = \tfrac{1}{\cos x}$。$\tfrac1u$ の公式から $\tfrac{\sin x}{\cos^2 x} = \sec x\tan x$。お椀の底（$x = 0$）で傾きは 0。|$\sec x = \tfrac{1}{\cos x}$。由 $\tfrac1u$ 的法则得 $\tfrac{\sin x}{\cos^2 x} = \sec x\tan x$。碗底（$x = 0$）斜率为 0。`,
      cs: R`Secant of an expression: $\sec u\tan u$ times $u'$. Type it as sec(...).|Sécante d’une expression : $\sec u\tan u$ fois $u'$. Tapez-la sec(...).|Secante de una expresión: $\sec u\tan u$ por $u'$. Escríbela sec(...).|式の正割は $\sec u\tan u$ に $u'$ を掛けます。sec(...) と入力します。|表达式的正割：$\sec u\tan u$ 乘 $u'$。输入为 sec(...)。`,
      eg: [R`(\sec 2x)' = 2\sec 2x\tan 2x`], ega: '1/cos(2x)', egpa: '2sin(2x)/cos(2x)^2', egx: [-0.75, 0.75], egy: [-6, 8],
      ex: { q: R`f(x) = \sec(x^2)`, f: '1/cos(x^2)', sol: [R`u = x^2,\ u' = 2x`, R`f'(x) = 2x\sec(x^2)\tan(x^2)`] } },
    { f: R`\csc x`, fp: R`-\csc x\cot x`, fu: R`-\csc u\cot u\cdot u'`, fa: '1/sin(x)', fpa: '-cos(x)/sin(x)^2', xw: [0.1, 3.05], yw: [-5, 5],
      s: R`$\csc x = \tfrac{1}{\sin x}$, so the derivative is $-\tfrac{\cos x}{\sin^2 x} = -\csc x\cot x$. Like for cosine and cotangent, the “co-” function brings a minus sign.|$\csc x = \tfrac{1}{\sin x}$, donc la dérivée est $-\tfrac{\cos x}{\sin^2 x} = -\csc x\cot x$. Comme pour cosinus et cotangente, la fonction « co- » amène un signe moins.|$\csc x = \tfrac{1}{\sin x}$, así que la derivada es $-\tfrac{\cos x}{\sin^2 x} = -\csc x\cot x$. Como con el coseno y la cotangente, la función «co-» trae un signo menos.|$\csc x = \tfrac{1}{\sin x}$ なので導関数は $-\tfrac{\cos x}{\sin^2 x} = -\csc x\cot x$。cos や cot と同じく「余」の付く関数にはマイナスが付きます。|$\csc x = \tfrac{1}{\sin x}$，导数为 $-\tfrac{\cos x}{\sin^2 x} = -\csc x\cot x$。和余弦、余切一样，“余”函数带负号。`,
      cs: R`Cosecant of an expression: $-\csc u\cot u$ times $u'$. Type it as csc(...).|Cosécante d’une expression : $-\csc u\cot u$ fois $u'$. Tapez-la csc(...).|Cosecante de una expresión: $-\csc u\cot u$ por $u'$. Escríbela csc(...).|式の余割は $-\csc u\cot u$ に $u'$ を掛けます。csc(...) と入力します。|表达式的余割：$-\csc u\cot u$ 乘 $u'$。输入为 csc(...)。`,
      eg: [R`(\csc 3x)' = -3\csc 3x\cot 3x`], ega: '1/sin(3x)', egpa: '-3cos(3x)/sin(3x)^2', egx: [0.05, 1.0], egy: [-10, 10],
      ex: { q: R`f(x) = \csc(2x)`, f: '1/sin(2x)', sol: [R`u = 2x,\ u' = 2`, R`f'(x) = -2\csc(2x)\cot(2x)`] } },
    { f: R`\arcsin x`, fp: R`\frac{1}{\sqrt{1 - x^2}}`, fu: R`\frac{u'}{\sqrt{1 - u^2}}`, fa: 'asin(x)', fpa: '1/sqrt(1-x^2)', xw: [-1.4, 1.4], yw: [-2, 3.5],
      s: R`$\arcsin$ undoes $\sin$ on $[-1, 1]$. Its slope is 1 at the centre and becomes infinite at $\pm1$, where the curve stands vertical.|$\arcsin$ défait $\sin$ sur $[-1, 1]$. Sa pente vaut 1 au centre et devient infinie en $\pm1$, où la courbe devient verticale.|$\arcsin$ deshace $\sin$ en $[-1, 1]$. Su pendiente es 1 en el centro y se hace infinita en $\pm1$, donde la curva se pone vertical.|$\arcsin$ は $[-1, 1]$ で $\sin$ を元に戻す関数。中央で傾き 1、$\pm1$ では曲線が垂直になり傾きは無限大。|$\arcsin$ 在 $[-1, 1]$ 上是 $\sin$ 的反函数。中心斜率为 1，在 $\pm1$ 处曲线竖直，斜率趋于无穷。`,
      cs: R`With an expression inside: $u'$ over $\sqrt{1 - u^2}$. Type arcsin as asin(...) or arcsin(...).|Avec une expression à l’intérieur : $u'$ sur $\sqrt{1 - u^2}$. Tapez arcsin sous la forme asin(...) ou arcsin(...).|Con una expresión dentro: $u'$ entre $\sqrt{1 - u^2}$. Escribe arcsin como asin(...) o arcsin(...).|中が式なら $u'$ ÷ $\sqrt{1 - u^2}$。asin(...) または arcsin(...) と入力します。|内层是表达式：$u'$ 除以 $\sqrt{1 - u^2}$。输入为 asin(...) 或 arcsin(...)。`,
      eg: [R`(\arcsin 2x)' = \frac{2}{\sqrt{1 - 4x^2}}`], ega: 'asin(2x)', egpa: '2/sqrt(1-4x^2)', egx: [-0.7, 0.7], egy: [-2, 6],
      ex: { q: R`f(x) = \arcsin\frac x2`, f: 'asin(x/2)', sol: [R`u = \tfrac x2,\ u' = \tfrac12`, R`f'(x) = \frac{1/2}{\sqrt{1 - x^2/4}} = \frac{1}{\sqrt{4 - x^2}}`] } },
    { f: R`\arccos x`, fp: R`-\frac{1}{\sqrt{1 - x^2}}`, fu: R`-\frac{u'}{\sqrt{1 - u^2}}`, fa: 'acos(x)', fpa: '-1/sqrt(1-x^2)', xw: [-1.4, 1.4], yw: [-3.5, 3.5],
      s: R`$\arccos x = \tfrac\pi2 - \arcsin x$, so its derivative is just the arcsine’s with a minus sign: the curve always goes down.|$\arccos x = \tfrac\pi2 - \arcsin x$ : sa dérivée est celle de l’arcsinus avec un signe moins ; la courbe descend toujours.|$\arccos x = \tfrac\pi2 - \arcsin x$, así que su derivada es la del arcoseno con un signo menos: la curva siempre baja.|$\arccos x = \tfrac\pi2 - \arcsin x$ なので、導関数は $\arcsin$ のものにマイナスを付けただけ。曲線は常に減少します。|$\arccos x = \tfrac\pi2 - \arcsin x$，导数就是反正弦的导数加负号：曲线一直下降。`,
      cs: R`With an expression inside: minus $u'$ over $\sqrt{1 - u^2}$.|Avec une expression à l’intérieur : moins $u'$ sur $\sqrt{1 - u^2}$.|Con una expresión dentro: menos $u'$ entre $\sqrt{1 - u^2}$.|中が式なら $-u'$ ÷ $\sqrt{1 - u^2}$。|内层是表达式：负的 $u'$ 除以 $\sqrt{1 - u^2}$。`,
      eg: [R`\big(\arccos x^2\big)' = -\frac{2x}{\sqrt{1 - x^4}}`], ega: 'acos(x^2)', egpa: '-2x/sqrt(1-x^4)', egx: [-1.2, 1.2], egy: [-5, 5],
      ex: { q: R`f(x) = \arccos\frac x3`, f: 'acos(x/3)', sol: [R`u = \tfrac x3,\ u' = \tfrac13`, R`f'(x) = -\frac{1/3}{\sqrt{1 - x^2/9}} = -\frac{1}{\sqrt{9 - x^2}}`] } },
    { f: R`\arctan x`, fp: R`\frac{1}{1 + x^2}`, fu: R`\frac{u'}{1 + u^2}`, fa: 'atan(x)', fpa: '1/(1+x^2)', xw: [-5, 5], yw: [-1.9, 1.9],
      s: R`$\arctan$ rises from $-\tfrac\pi2$ to $\tfrac\pi2$. Its slope $\tfrac{1}{1 + x^2}$ is the bell on the board: 1 at the centre, fading to 0 far away. It appears all the time in integrals.|$\arctan$ monte de $-\tfrac\pi2$ à $\tfrac\pi2$. Sa pente $\tfrac{1}{1 + x^2}$ est la cloche du tableau : 1 au centre, tendant vers 0 au loin. Elle revient sans cesse dans les intégrales.|$\arctan$ sube de $-\tfrac\pi2$ a $\tfrac\pi2$. Su pendiente $\tfrac{1}{1 + x^2}$ es la campana de la pizarra: 1 en el centro y tendiendo a 0 lejos. Aparece continuamente en las integrales.|$\arctan$ は $-\tfrac\pi2$ から $\tfrac\pi2$ まで増加。傾き $\tfrac{1}{1 + x^2}$ は黒板の釣り鐘形：中央で 1、遠くでは 0 に近づきます。積分でよく現れます。|$\arctan$ 从 $-\tfrac\pi2$ 升到 $\tfrac\pi2$。斜率 $\tfrac{1}{1 + x^2}$ 就是黑板上的钟形：中心为 1，远处趋于 0。在积分中经常出现。`,
      cs: R`With an expression inside: $u'$ over $1 + u^2$. Type arctan as atan(...) or arctan(...).|Avec une expression à l’intérieur : $u'$ sur $1 + u^2$. Tapez arctan sous la forme atan(...) ou arctan(...).|Con una expresión dentro: $u'$ entre $1 + u^2$. Escribe arctan como atan(...) o arctan(...).|中が式なら $u'$ ÷ $(1 + u^2)$。atan(...) または arctan(...) と入力します。|内层是表达式：$u'$ 除以 $1 + u^2$。输入为 atan(...) 或 arctan(...)。`,
      eg: [R`\big(\arctan x^2\big)' = \frac{2x}{1 + x^4}`], ega: 'atan(x^2)', egpa: '2x/(1+x^4)', egx: [-3, 3], egy: [-1.4, 1.9],
      ex: { q: R`f(x) = \arctan(2x)`, f: 'atan(2x)', sol: [R`u = 2x,\ u' = 2`, R`f'(x) = \frac{2}{1 + 4x^2}`] } },
    { f: R`\operatorname{arccot} x`, fp: R`-\frac{1}{1 + x^2}`, fu: R`-\frac{u'}{1 + u^2}`, fa: 'pi/2-atan(x)', fpa: '-1/(1+x^2)', xw: [-5, 5], yw: [-1.3, 3.4],
      s: R`$\operatorname{arccot} x = \tfrac\pi2 - \arctan x$ falls from $\pi$ to 0, so its slope is the arctangent’s with a minus sign.|$\operatorname{arccot} x = \tfrac\pi2 - \arctan x$ descend de $\pi$ à 0 : sa pente est celle de l’arctangente avec un signe moins.|$\operatorname{arccot} x = \tfrac\pi2 - \arctan x$ baja de $\pi$ a 0, así que su pendiente es la del arcotangente con un signo menos.|$\operatorname{arccot} x = \tfrac\pi2 - \arctan x$ は $\pi$ から 0 へ減少するので、傾きは $\arctan$ のものにマイナスを付けたもの。|$\operatorname{arccot} x = \tfrac\pi2 - \arctan x$ 从 $\pi$ 降到 0，斜率为反正切的斜率加负号。`,
      cs: R`With an expression inside: minus $u'$ over $1 + u^2$. Type it as arccot(...).|Avec une expression à l’intérieur : moins $u'$ sur $1 + u^2$. Tapez arccot(...).|Con una expresión dentro: menos $u'$ entre $1 + u^2$. Escríbelo arccot(...).|中が式なら $-u'$ ÷ $(1 + u^2)$。arccot(...) と入力します。|内层是表达式：负的 $u'$ 除以 $1 + u^2$。输入为 arccot(...)。`,
      eg: [R`(\operatorname{arccot} 3x)' = -\frac{3}{1 + 9x^2}`], ega: 'pi/2-atan(3x)', egpa: '-3/(1+9x^2)', egx: [-2, 2], egy: [-3.3, 3.4],
      ex: { q: R`f(x) = \operatorname{arccot}(x^2)`, f: 'pi/2-atan(x^2)', sol: [R`u = x^2,\ u' = 2x`, R`f'(x) = -\frac{2x}{1 + x^4}`] } }
  ];

  // two texts 'en|fr|…' put together language by language
  const join = (a, b) => { const B = b.split('|'); return a.split('|').map((x, i) => x + ' ' + B[i]).join('|'); };
  const lessons = {};
  for (const r of ROWS) {
    const h = head(R`f(x) = ` + r.f);
    lessons['Table of derivatives/' + r.f] = [
      { t: RULE, s: join(r.s, LEG), a: [h, F(R`f(x) = ` + r.f), Y(R`f'(x) = ` + r.fp, { d: 500 }), ...graph(r.fa, r.fpa, r.xw, r.yw)] },
      { t: CHAIN, s: r.cs, a: [['clr'], h, F(R`\big(f(u)\big)' = ` + r.fu), ...r.eg.map((l, i) => Y(l, { d: 500 + i * 700 })), ...graph(r.ega, r.egpa, r.egx, r.egy)] },
      { t: YOUR, s: TRY, a: [['clr'], h, F(r.ex.q, { c: 'b' }), ...graph(r.ex.f, r.ex.f, null, null).slice(0, 2)], ex: Object.assign({ k: 'der' }, r.ex) }
    ];
  }

  // =============================== the other cards of the derivatives sheet ===============================
  const IDEA = 'The idea|L’idée|La idea|考え方|思路', EX = 'Worked example|Exemple résolu|Ejemplo resuelto|例題|例题';
  const TRYV = 'Work it out on paper, type the answer and check it. Each hint writes the next line of the solution on the board.|Faites le calcul sur papier, tapez la réponse et vérifiez. Chaque indice écrit la ligne suivante de la solution au tableau.|Hazlo en papel, escribe la respuesta y compruébala. Cada pista escribe en la pizarra la siguiente línea de la solución.|紙で計算し、答えを入力して確かめましょう。ヒントごとに解答が 1 行ずつ黒板に書かれます。|先在纸上算，输入答案并检查。每次提示会在黑板上写出解答的下一行。';
  const H = name => ['t', name, { head: true, s: 16, c: 'y' }];
  const W = (txt, o = {}) => ['t', txt, Object.assign({ s: 18, c: 'b' }, o)];
  const AX = (xw, yw) => ['ax', { xw, yw }], P = (eq, c = 'y', o = {}) => ['p', 'y=' + eq, Object.assign({ c }, o)];
  const PT = (x, y, lab, c = 'o') => ['pt', x, y, lab || '', { c }];
  const card = (key, name, idea, ex, your) => {
    lessons[key] = [{ t: IDEA, s: idea.s, a: [H(name), ...idea.a] }, { t: EX, s: ex.s, a: [['clr'], H(name), ...ex.a] },
      { t: YOUR, s: your.ex.k === 'der' ? TRY : TRYV, a: [['clr'], H(name), ...(your.a || [])], ex: your.ex }];
  };
  const dq = f => `Differentiate $${f}$.|Dérivez $${f}$.|Deriva $${f}$.|$${f}$ を微分せよ。|求 $${f}$ 的导数。`;

  card('Table of derivatives/The chain-rule column', 'The chain-rule column|La colonne « dérivation en chaîne »|La columna de la regla de la cadena|合成関数の列|链式法则一栏',
    { s: R`The right column of the table is the same rule with an expression $u$ in place of $x$: differentiate the outside function as usual, keep the inside as it is, then multiply by $u'$. Forgetting that last factor is the most common mistake.|La colonne de droite du tableau est la même règle avec une expression $u$ à la place de $x$ : on dérive la fonction extérieure normalement, on garde l’intérieur tel quel, puis on multiplie par $u'$. Oublier ce dernier facteur est l’erreur la plus fréquente.|La columna derecha de la tabla es la misma regla con una expresión $u$ en lugar de $x$: deriva la función exterior como siempre, deja el interior igual y multiplica por $u'$. Olvidar ese último factor es el error más común.|表の右の列は $x$ の代わりに式 $u$ を入れた同じ規則：外側を普通に微分し、中身はそのまま、最後に $u'$ を掛ける。この掛け忘れが最も多いミス。|表格右栏是把 $x$ 换成表达式 $u$ 的同一法则：外层照常求导，内层保持不变，再乘以 $u'$。忘了最后这个因子是最常见的错误。`,
      a: [Y(R`\big(f(u)\big)' = f'(u)\cdot u'`), W('outside, keep the inside, times u′|extérieur, intérieur inchangé, fois u′|exterior, interior igual, por u′|外側を微分、中身はそのまま、u′ を掛ける|外层求导，内层不变，乘以 u′'), AX([-2.5, 2.5], [-5, 5]), P('sin(x^2)'), P('2x*cos(x^2)', 'b', { d: 400 })] },
    { s: R`$(\sin x^2)'$: the outside is $\sin$, whose derivative is $\cos$; the inside $x^2$ stays; then multiply by $(x^2)' = 2x$: $\cos x^2\cdot 2x$. And $(e^{3x})' = e^{3x}\cdot 3$.|$(\sin x^2)'$ : l’extérieur est $\sin$, de dérivée $\cos$ ; l’intérieur $x^2$ reste ; puis on multiplie par $(x^2)' = 2x$ : $\cos x^2\cdot 2x$. Et $(e^{3x})' = e^{3x}\cdot 3$.|$(\sin x^2)'$: el exterior es $\sin$, de derivada $\cos$; el interior $x^2$ se queda; luego se multiplica por $(x^2)' = 2x$: $\cos x^2\cdot 2x$. Y $(e^{3x})' = e^{3x}\cdot 3$.|$(\sin x^2)' = \cos x^2\cdot 2x$、$(e^{3x})' = 3e^{3x}$。|$(\sin x^2)' = \cos x^2\cdot 2x$，$(e^{3x})' = 3e^{3x}$。`,
      a: [F(R`(\sin x^2)' = \cos x^2\cdot 2x`), Y(R`(e^{3x})' = 3e^{3x}`)] },
    { a: [F(R`f(x) = \sin(3x^2)`, { c: 'b' })],
      ex: { k: 'der', q: R`f(x) = \sin(3x^2)`, f: 'sin(3x^2)', sol: [R`u = 3x^2,\ u' = 6x`, R`f'(x) = 6x\cos(3x^2)`] } });

  card('Table of derivatives/Variable base and exponent', 'Variable base and exponent|Base et exposant variables|Base y exponente variables|底も指数も変数|底与指数都含变量',
    { s: R`For $u^v$ with $x$ in both places, neither the power rule nor the exponential rule applies. Write $u^v = e^{v\ln u}$ and use the chain rule; the bracket is the derivative of the exponent $v\ln u$.|Pour $u^v$ avec $x$ aux deux endroits, ni la règle des puissances ni celle de l’exponentielle ne s’applique. On écrit $u^v = e^{v\ln u}$ et on utilise la dérivation en chaîne ; la parenthèse est la dérivée de l’exposant $v\ln u$.|Para $u^v$ con $x$ en los dos sitios no sirven ni la regla de la potencia ni la de la exponencial. Escribe $u^v = e^{v\ln u}$ y usa la regla de la cadena; el paréntesis es la derivada del exponente $v\ln u$.|$u^v$ で底にも指数にも $x$ があると、累乗の公式も指数関数の公式も使えない。$u^v = e^{v\ln u}$ と書いて合成関数の微分。括弧は指数 $v\ln u$ の微分。|当 $u^v$ 底和指数都含 $x$ 时，幂法则和指数法则都不适用。写成 $u^v = e^{v\ln u}$ 再用链式法则；括号就是指数 $v\ln u$ 的导数。`,
      a: [F(R`u^v = e^{v\ln u}`), Y(R`(u^v)' = u^v\left(v'\ln u + \frac{v\,u'}{u}\right)`), AX([0.05, 2], [-0.5, 4.5]), P('x^x'), P('x^x*(ln(x)+1)', 'b', { d: 400 })] },
    { s: R`$x^x = e^{x\ln x}$, and $(x\ln x)' = \ln x + 1$, so $(x^x)' = x^x(\ln x + 1)$. It is 0 at $x = \tfrac1e$, where $x^x$ has its minimum.|$x^x = e^{x\ln x}$ et $(x\ln x)' = \ln x + 1$, donc $(x^x)' = x^x(\ln x + 1)$. Elle s’annule en $x = \tfrac1e$, où $x^x$ est minimale.|$x^x = e^{x\ln x}$ y $(x\ln x)' = \ln x + 1$, así que $(x^x)' = x^x(\ln x + 1)$. Se anula en $x = \tfrac1e$, donde $x^x$ es mínima.|$x^x = e^{x\ln x}$、$(x\ln x)' = \ln x + 1$ より $(x^x)' = x^x(\ln x + 1)$。$x = \tfrac1e$ で 0（最小）。|$x^x = e^{x\ln x}$，$(x\ln x)' = \ln x + 1$，所以 $(x^x)' = x^x(\ln x + 1)$，在 $x = \tfrac1e$ 处为 0（最小值）。`,
      a: [F(R`x^x = e^{x\ln x},\quad (x\ln x)' = \ln x + 1`), Y(R`(x^x)' = x^x(\ln x + 1)`), AX([0.05, 2], [-0.5, 4.5]), P('x^x'), PT(1 / Math.E, Math.pow(1 / Math.E, 1 / Math.E), 'x = 1/e')] },
    { a: [F(R`f(x) = x^{2x}`, { c: 'b' })],
      ex: { k: 'der', q: R`f(x) = x^{2x}\quad (x > 0)`, f: 'x^(2x)', sol: [R`x^{2x} = e^{2x\ln x}`, R`(2x\ln x)' = 2\ln x + 2`, R`f'(x) = x^{2x}(2\ln x + 2)`] } });

  card('Definition and tangent/Definition', 'The definition of the derivative|La définition du nombre dérivé|La definición de derivada|微分係数の定義|导数的定义',
    { s: R`$\tfrac{f(a + h) - f(a)}{h}$ is the slope of the chord from $a$ to $a + h$. Let $h$ shrink to 0 and the chord turns into the tangent: its slope is $f'(a)$. In exercises, expand, cancel the $h$, then set $h = 0$.|$\tfrac{f(a + h) - f(a)}{h}$ est la pente de la corde entre $a$ et $a + h$. Quand $h$ tend vers 0, la corde devient la tangente : sa pente est $f'(a)$. En exercice : on développe, on simplifie par $h$, puis on pose $h = 0$.|$\tfrac{f(a + h) - f(a)}{h}$ es la pendiente de la cuerda de $a$ a $a + h$. Al tender $h$ a 0 la cuerda se convierte en la tangente: su pendiente es $f'(a)$. En ejercicios: desarrolla, simplifica la $h$ y haz $h = 0$.|$\tfrac{f(a + h) - f(a)}{h}$ は $a$ から $a + h$ への弦の傾き。$h \to 0$ で弦は接線になり、その傾きが $f'(a)$。演習では展開し、$h$ で約分してから $h = 0$。|$\tfrac{f(a + h) - f(a)}{h}$ 是从 $a$ 到 $a + h$ 的割线斜率。令 $h \to 0$，割线变成切线，斜率为 $f'(a)$。做题时：展开，约去 $h$，再令 $h = 0$。`,
      a: [Y(R`f'(a) = \lim_{h\to0}\frac{f(a + h) - f(a)}{h}`), AX([-0.5, 4.5], [-1, 14]), P('x^2'), ['ln', 1, 1, 3.5, 12.25, { c: 'b' }], ['tan', 2], PT(2, 4, 'a'), PT(3.5, 12.25, 'a + h', 'b')] },
    { s: R`$f(x) = x^2$ at $a = 3$: $\tfrac{(3 + h)^2 - 9}{h} = \tfrac{6h + h^2}{h} = 6 + h$, which tends to 6. So $f'(3) = 6$, as the rule $2x$ predicts.|$f(x) = x^2$ en $a = 3$ : $\tfrac{(3 + h)^2 - 9}{h} = \tfrac{6h + h^2}{h} = 6 + h$, qui tend vers 6. Donc $f'(3) = 6$, comme le prévoit $2x$.|$f(x) = x^2$ en $a = 3$: $\tfrac{(3 + h)^2 - 9}{h} = \tfrac{6h + h^2}{h} = 6 + h$, que tiende a 6. Así $f'(3) = 6$, como predice $2x$.|$f(x) = x^2$、$a = 3$：$\tfrac{(3 + h)^2 - 9}{h} = 6 + h \to 6$。$2x$ の予想通り $f'(3) = 6$。|$f(x) = x^2$，$a = 3$：$\tfrac{(3 + h)^2 - 9}{h} = 6 + h \to 6$，与 $2x$ 一致。`,
      a: [F(R`\frac{(3 + h)^2 - 9}{h} = \frac{6h + h^2}{h} = 6 + h`), Y(R`\to 6 = f'(3)`)] },
    { a: [F(R`f(x) = \frac1x,\quad a = 2`, { c: 'b' }), AX([0.2, 5], [-0.2, 2.5]), P('1/x'), PT(2, 0.5, 'a = 2')],
      ex: { k: 'val', v: '-1/4', q: R`Use the definition to find $f'(2)$ for $f(x) = \frac1x$.|Utilisez la définition pour calculer $f'(2)$ si $f(x) = \frac1x$.|Usa la definición para hallar $f'(2)$ si $f(x) = \frac1x$.|定義を用いて $f(x) = \frac1x$ の $f'(2)$ を求めよ。|用定义求 $f(x) = \frac1x$ 的 $f'(2)$。`,
        sol: [R`\frac{\frac{1}{2 + h} - \frac12}{h} = \frac{2 - (2 + h)}{2h(2 + h)}`, R`= -\frac{1}{2(2 + h)}`, R`\to -\frac14`] } });

  card('Definition and tangent/Tangent line', 'Tangent line|Équation de la tangente|Recta tangente|接線の方程式|切线方程',
    { s: R`The tangent at $a$ passes through the point $(a, f(a))$ with slope $f'(a)$. Plug both into the point–slope form. Three numbers to compute: $a$, $f(a)$ and $f'(a)$.|La tangente en $a$ passe par $(a, f(a))$ avec la pente $f'(a)$. On les met dans la forme point–pente. Trois nombres à calculer : $a$, $f(a)$ et $f'(a)$.|La tangente en $a$ pasa por $(a, f(a))$ con pendiente $f'(a)$. Pon ambos en la forma punto–pendiente. Tres números: $a$, $f(a)$ y $f'(a)$.|$a$ での接線は点 $(a, f(a))$ を通り傾き $f'(a)$。点傾き形に代入。求める数は $a$, $f(a)$, $f'(a)$ の 3 つ。|在 $a$ 处的切线过点 $(a, f(a))$、斜率为 $f'(a)$，代入点斜式。要算三个数：$a$、$f(a)$、$f'(a)$。`,
      a: [Y(R`y = f(a) + f'(a)(x - a)`), AX([-1, 3], [-1.5, 6]), P('x^2'), ['tan', 1], PT(1, 1, '(1, 1)')] },
    { s: R`$f(x) = x^2$ at $a = 1$: $f(1) = 1$, $f'(1) = 2$, so $y = 1 + 2(x - 1) = 2x - 1$.|$f(x) = x^2$ en $a = 1$ : $f(1) = 1$, $f'(1) = 2$, donc $y = 1 + 2(x - 1) = 2x - 1$.|$f(x) = x^2$ en $a = 1$: $f(1) = 1$, $f'(1) = 2$, así que $y = 1 + 2(x - 1) = 2x - 1$.|$f(x) = x^2$、$a = 1$：$y = 1 + 2(x - 1) = 2x - 1$。|$f(x) = x^2$，$a = 1$：$y = 1 + 2(x - 1) = 2x - 1$。`,
      a: [F(R`f(1) = 1,\quad f'(1) = 2`), Y(R`y = 2x - 1`), AX([-1, 3], [-1.5, 6]), P('x^2'), P('2x-1', 'b')] },
    { a: [F(R`f(x) = x^3 - 2x,\quad a = 1`, { c: 'b' }), AX([-2, 2.5], [-3, 4]), P('x^3-2x')],
      ex: { k: 'expr', f: 'x-2', q: R`Find the tangent to $f(x) = x^3 - 2x$ at $x = 1$ (type $y = \dots$).|Trouvez la tangente à $f(x) = x^3 - 2x$ en $x = 1$ (tapez $y = \dots$).|Halla la tangente a $f(x) = x^3 - 2x$ en $x = 1$ (escribe $y = \dots$).|$f(x) = x^3 - 2x$ の $x = 1$ における接線を $y = \dots$ で答えよ。|求 $f(x) = x^3 - 2x$ 在 $x = 1$ 处的切线（写 $y = \dots$）。`,
        sol: [R`f(1) = -1,\quad f'(x) = 3x^2 - 2,\ f'(1) = 1`, R`y = -1 + (x - 1) = x - 2`] } });

  card('Definition and tangent/Normal line', 'Normal line|Équation de la normale|Recta normal|法線の方程式|法线方程',
    { s: R`The normal is perpendicular to the tangent at the same point, so its slope is $-\tfrac{1}{f'(a)}$ (perpendicular slopes multiply to $-1$). If $f'(a) = 0$ the tangent is horizontal and the normal is the vertical line $x = a$.|La normale est perpendiculaire à la tangente au même point : sa pente vaut $-\tfrac{1}{f'(a)}$ (les pentes perpendiculaires ont un produit $-1$). Si $f'(a) = 0$ la tangente est horizontale et la normale est la verticale $x = a$.|La normal es perpendicular a la tangente en el mismo punto, así que su pendiente es $-\tfrac{1}{f'(a)}$ (pendientes perpendiculares multiplican $-1$). Si $f'(a) = 0$ la tangente es horizontal y la normal es la vertical $x = a$.|法線は同じ点で接線に垂直なので傾きは $-\tfrac{1}{f'(a)}$（垂直な傾きの積は $-1$）。$f'(a) = 0$ なら法線は $x = a$。|法线在同一点垂直于切线，斜率为 $-\tfrac{1}{f'(a)}$（垂直斜率之积为 $-1$）。若 $f'(a) = 0$，法线是竖直线 $x = a$。`,
      a: [Y(R`y = f(a) - \frac{1}{f'(a)}(x - a)`), AX([-1.5, 3], [-1, 4]), P('x^2'), P('2x-1', 'b'), P('1.5-x/2', 'g', { d: 300 }), PT(1, 1, '')] },
    { s: R`$f(x) = x^2$ at $a = 1$: the tangent slope is 2, so the normal slope is $-\tfrac12$: $y = 1 - \tfrac12(x - 1)$.|$f(x) = x^2$ en $a = 1$ : pente de la tangente 2, donc pente de la normale $-\tfrac12$ : $y = 1 - \tfrac12(x - 1)$.|$f(x) = x^2$ en $a = 1$: la pendiente de la tangente es 2, así que la de la normal es $-\tfrac12$: $y = 1 - \tfrac12(x - 1)$.|$f(x) = x^2$、$a = 1$：法線の傾き $-\tfrac12$、$y = 1 - \tfrac12(x - 1)$。|$f(x) = x^2$，$a = 1$：法线斜率 $-\tfrac12$，$y = 1 - \tfrac12(x - 1)$。`,
      a: [F(R`m_{\text{normal}} = -\tfrac12`), Y(R`y = 1 - \tfrac12(x - 1) = \tfrac32 - \tfrac x2`)] },
    { a: [F(R`f(x) = \sqrt x,\quad a = 4`, { c: 'b' }), AX([-0.5, 8], [-0.5, 4]), P('sqrt(x)'), PT(4, 2, '(4, 2)')],
      ex: { k: 'expr', f: '18-4x', q: R`Find the normal to $y = \sqrt x$ at $x = 4$ (type $y = \dots$).|Trouvez la normale à $y = \sqrt x$ en $x = 4$ (tapez $y = \dots$).|Halla la normal a $y = \sqrt x$ en $x = 4$ (escribe $y = \dots$).|$y = \sqrt x$ の $x = 4$ における法線を $y = \dots$ で答えよ。|求 $y = \sqrt x$ 在 $x = 4$ 处的法线（写 $y = \dots$）。`,
        sol: [R`f(4) = 2,\quad f'(4) = \frac{1}{2\sqrt4} = \frac14`, R`m = -4:\ y = 2 - 4(x - 4) = 18 - 4x`] } });

  card('Definition and tangent/Linear approximation', 'Linear approximation|Approximation affine|Aproximación lineal|1 次近似|线性近似',
    { s: R`Close to $a$, the curve and its tangent are almost the same, so the tangent gives a quick estimate of $f(a + h)$ for small $h$. Choose $a$ where $f$ is easy (a perfect square, 0, a known angle).|Près de $a$, la courbe et sa tangente se confondent presque : la tangente donne une estimation rapide de $f(a + h)$ pour $h$ petit. On choisit $a$ là où $f$ est facile (un carré parfait, 0, un angle connu).|Cerca de $a$ la curva y su tangente casi coinciden, así que la tangente da una estimación rápida de $f(a + h)$ para $h$ pequeño. Elige $a$ donde $f$ sea fácil (un cuadrado perfecto, 0, un ángulo conocido).|$a$ の近くで曲線と接線はほぼ同じなので、小さい $h$ について $f(a + h)$ を接線で見積もれる。$a$ は計算が楽な点（平方数、0、既知の角）を選ぶ。|在 $a$ 附近曲线与切线几乎一样，所以用切线快速估计小 $h$ 时的 $f(a + h)$。$a$ 选在 $f$ 好算的地方（完全平方数、0、已知角）。`,
      a: [Y(R`f(a + h) \approx f(a) + f'(a)\,h`), AX([2, 6.5], [1.3, 2.6]), P('sqrt(x)'), ['tan', 4], PT(4, 2, 'a = 4')] },
    { s: R`$\sqrt{4.1}$: take $a = 4$, $h = 0.1$: $2 + \tfrac{1}{4}\cdot 0.1 = 2.025$. The true value is $2.0248\ldots$|$\sqrt{4{,}1}$ : $a = 4$, $h = 0{,}1$ : $2 + \tfrac14\cdot 0{,}1 = 2{,}025$. La vraie valeur est $2{,}0248\ldots$|$\sqrt{4{,}1}$: $a = 4$, $h = 0{,}1$: $2 + \tfrac14\cdot 0{,}1 = 2{,}025$. El valor real es $2{,}0248\ldots$|$\sqrt{4.1} \approx 2 + \tfrac14\cdot 0.1 = 2.025$（真値 $2.0248\ldots$）。|$\sqrt{4.1} \approx 2 + \tfrac14\cdot 0.1 = 2.025$（真值 $2.0248\ldots$）。`,
      a: [F(R`f(x) = \sqrt x,\ a = 4,\ f'(4) = \tfrac14`), Y(R`\sqrt{4.1} \approx 2 + \tfrac14\cdot 0.1 = 2.025`)] },
    { a: [F(R`\sqrt[3]{8.12}`, { c: 'b' })],
      ex: { k: 'val', v: '2.01', q: R`Use a linear approximation at $a = 8$ to estimate $\sqrt[3]{8.12}$.|Utilisez l’approximation affine en $a = 8$ pour estimer $\sqrt[3]{8{,}12}$.|Usa la aproximación lineal en $a = 8$ para estimar $\sqrt[3]{8{,}12}$.|$a = 8$ での 1 次近似で $\sqrt[3]{8.12}$ を見積もれ。|用 $a = 8$ 处的线性近似估计 $\sqrt[3]{8.12}$。`,
        sol: [R`f(x) = x^{1/3},\ f'(8) = \frac{1}{3\cdot 8^{2/3}} = \frac1{12}`, R`\approx 2 + \frac{0.12}{12} = 2.01`] } });

  card('Rules/Power and constant', 'Powers and constants|Puissances et constantes|Potencias y constantes|累乗と定数|幂与常数',
    { s: R`Differentiate term by term: bring each exponent down and lower it by one; a constant on its own disappears; a constant factor stays. Rewrite roots and fractions as powers first: $\sqrt x = x^{1/2}$, $\tfrac1x = x^{-1}$.|On dérive terme à terme : on descend chaque exposant et on le diminue de 1 ; une constante seule disparaît ; un facteur constant reste. On réécrit d’abord racines et fractions en puissances : $\sqrt x = x^{1/2}$, $\tfrac1x = x^{-1}$.|Deriva término a término: baja cada exponente y réstale uno; una constante sola desaparece; un factor constante se queda. Antes, escribe raíces y fracciones como potencias: $\sqrt x = x^{1/2}$, $\tfrac1x = x^{-1}$.|項ごとに微分：指数を前に下ろして 1 減らす。定数だけの項は消え、定数倍は残る。根号や分数は先に累乗に：$\sqrt x = x^{1/2}$、$\tfrac1x = x^{-1}$。|逐项求导：指数拿下来再减 1；单独的常数消失；常数因子保留。先把根式、分式写成幂：$\sqrt x = x^{1/2}$，$\tfrac1x = x^{-1}$。`,
      a: [Y(R`(x^n)' = nx^{n-1},\quad (c)' = 0,\quad (cf)' = cf'`), AX([-2, 2.2], [-12, 25]), P('3x^4-5x^2+7'), P('12x^3-10x', 'b', { d: 400 })] },
    { s: R`$(3x^4 - 5x^2 + 7)' = 12x^3 - 10x$. On the graph the blue derivative is 0 exactly where the yellow curve turns.|$(3x^4 - 5x^2 + 7)' = 12x^3 - 10x$. Sur le graphique, la dérivée bleue s’annule exactement là où la courbe jaune tourne.|$(3x^4 - 5x^2 + 7)' = 12x^3 - 10x$. En la gráfica la derivada azul vale 0 justo donde la curva amarilla da la vuelta.|$(3x^4 - 5x^2 + 7)' = 12x^3 - 10x$。青い導関数は黄色の曲線が向きを変える所で 0。|$(3x^4 - 5x^2 + 7)' = 12x^3 - 10x$。蓝色导数在黄色曲线转折处为 0。`,
      a: [Y(R`(3x^4 - 5x^2 + 7)' = 12x^3 - 10x`)] },
    { a: [F(R`f(x) = 4x^5 - \frac3x + 2\sqrt x`, { c: 'b' })],
      ex: { k: 'der', q: R`f(x) = 4x^5 - \frac3x + 2\sqrt x`, f: '4x^5-3/x+2sqrt(x)', sol: [R`= 4x^5 - 3x^{-1} + 2x^{1/2}`, R`f'(x) = 20x^4 + 3x^{-2} + x^{-1/2} = 20x^4 + \frac{3}{x^2} + \frac{1}{\sqrt x}`] } });

  card('Rules/Sum', 'Sums and differences|Sommes et différences|Sumas y restas|和と差|和与差',
    { s: R`The derivative of a sum is the sum of the derivatives: slopes simply add. So you can always split a long expression into pieces and differentiate each piece with its own rule.|La dérivée d’une somme est la somme des dérivées : les pentes s’ajoutent. On peut donc toujours découper une longue expression et dériver chaque morceau avec sa règle.|La derivada de una suma es la suma de las derivadas: las pendientes se suman. Así siempre puedes partir una expresión larga y derivar cada trozo con su regla.|和の微分は微分の和（傾きは足し算）。長い式は分けて、各部分をそれぞれの公式で微分できる。|和的导数等于导数之和：斜率直接相加。所以长式子总能拆开，每部分用各自的法则求导。`,
      a: [Y(R`(f \pm g)' = f' \pm g'`), AX([-0.3, 6.5], [-8, 6]), P('x+sin(x)-x^2/4'), P('1+cos(x)-x/2', 'b', { d: 400 })] },
    { s: R`$(x^3 + \sin x - e^x)' = 3x^2 + \cos x - e^x$ — three independent pieces.|$(x^3 + \sin x - e^x)' = 3x^2 + \cos x - e^x$ — trois morceaux indépendants.|$(x^3 + \sin x - e^x)' = 3x^2 + \cos x - e^x$: tres trozos independientes.|$(x^3 + \sin x - e^x)' = 3x^2 + \cos x - e^x$（独立した 3 つの部分）。|$(x^3 + \sin x - e^x)' = 3x^2 + \cos x - e^x$——三个独立的部分。`,
      a: [Y(R`(x^3 + \sin x - e^x)' = 3x^2 + \cos x - e^x`)] },
    { a: [F(R`f(x) = 5x^2 - \cos x + \ln x`, { c: 'b' })],
      ex: { k: 'der', q: R`f(x) = 5x^2 - \cos x + \ln x`, f: '5x^2-cos(x)+ln(x)', sol: [R`(5x^2)' = 10x,\ (-\cos x)' = \sin x,\ (\ln x)' = \tfrac1x`, R`f'(x) = 10x + \sin x + \frac1x`] } });

  card('Rules/Product rule', 'Product rule|Dérivée d’un produit|Regla del producto|積の微分|乘积法则',
    { s: R`The derivative of a product is not the product of derivatives. Think of a rectangle with sides $f$ and $g$: when both grow, the area gains a strip $f'g$ and a strip $fg'$. “First derivative times second, plus first times second derivative.”|La dérivée d’un produit n’est pas le produit des dérivées. Pensez à un rectangle de côtés $f$ et $g$ : quand les deux grandissent, l’aire gagne une bande $f'g$ et une bande $fg'$.|La derivada de un producto no es el producto de derivadas. Piensa en un rectángulo de lados $f$ y $g$: cuando crecen, el área gana una franja $f'g$ y otra $fg'$.|積の微分は微分の積ではない。辺 $f$, $g$ の長方形を考えると、両方が伸びるとき面積は帯 $f'g$ と帯 $fg'$ だけ増える。|乘积的导数不是导数的乘积。想象边长为 $f$、$g$ 的矩形：两边增长时面积多出 $f'g$ 和 $fg'$ 两条。`,
      a: [Y(R`(fg)' = f'g + fg'`, { s: 30 }), W('(fg)′ ≠ f′g′|(fg)′ ≠ f′g′|(fg)′ ≠ f′g′|(fg)′ ≠ f′g′|(fg)′ ≠ f′g′', { c: 'p' }), AX([-0.3, 6.5], [-30, 15]), P('x^2*sin(x)'), P('2x*sin(x)+x^2*cos(x)', 'b', { d: 400 })] },
    { s: R`$(x^2\sin x)' = 2x\sin x + x^2\cos x$: derivative of $x^2$ times $\sin x$, plus $x^2$ times derivative of $\sin x$.|$(x^2\sin x)' = 2x\sin x + x^2\cos x$ : dérivée de $x^2$ fois $\sin x$, plus $x^2$ fois la dérivée de $\sin x$.|$(x^2\sin x)' = 2x\sin x + x^2\cos x$: derivada de $x^2$ por $\sin x$, más $x^2$ por la derivada de $\sin x$.|$(x^2\sin x)' = 2x\sin x + x^2\cos x$。|$(x^2\sin x)' = 2x\sin x + x^2\cos x$。`,
      a: [F(R`f = x^2,\ g = \sin x`), Y(R`(x^2\sin x)' = 2x\sin x + x^2\cos x`)] },
    { a: [F(R`f(x) = x^3e^x`, { c: 'b' })],
      ex: { k: 'der', q: R`f(x) = x^3e^x`, f: 'x^3*e^x', sol: [R`(x^3)' = 3x^2,\ (e^x)' = e^x`, R`f'(x) = 3x^2e^x + x^3e^x = x^2e^x(3 + x)`] } });

  card('Rules/Quotient rule', 'Quotient rule|Dérivée d’un quotient|Regla del cociente|商の微分|商的法则',
    { s: R`“Low d-high minus high d-low, over low squared”: the order on top matters because of the minus sign. The denominator is never expanded — leave it as $g^2$.|« Dérivée du haut fois le bas, moins le haut fois la dérivée du bas, sur le bas au carré » : l’ordre compte à cause du signe moins. On ne développe pas le dénominateur — on le laisse en $g^2$.|«Derivada de arriba por abajo menos arriba por derivada de abajo, entre abajo al cuadrado»: el orden importa por el signo menos. El denominador no se desarrolla: se deja como $g^2$.|「上の微分 × 下 − 上 × 下の微分、それを下の 2 乗で割る」。マイナスがあるので順序が大事。分母は展開せず $g^2$ のまま。|“上导乘下减上乘下导，除以下的平方”：因有减号，顺序很重要。分母不要展开，保留 $g^2$。`,
      a: [Y(R`\left(\frac fg\right)' = \frac{f'g - fg'}{g^2}`), AX([-4, 4], [-0.8, 1.2]), P('x/(x^2+1)'), P('(1-x^2)/(x^2+1)^2', 'b', { d: 400 })] },
    { s: R`$\left(\tfrac{x}{x^2 + 1}\right)' = \tfrac{1\cdot(x^2 + 1) - x\cdot 2x}{(x^2 + 1)^2} = \tfrac{1 - x^2}{(x^2 + 1)^2}$: zero at $x = \pm1$, where the curve has its maximum and minimum.|$\left(\tfrac{x}{x^2 + 1}\right)' = \tfrac{1 - x^2}{(x^2 + 1)^2}$ : nulle en $x = \pm1$, où la courbe a son maximum et son minimum.|$\left(\tfrac{x}{x^2 + 1}\right)' = \tfrac{1 - x^2}{(x^2 + 1)^2}$: se anula en $x = \pm1$, donde la curva tiene su máximo y su mínimo.|$\left(\tfrac{x}{x^2 + 1}\right)' = \tfrac{1 - x^2}{(x^2 + 1)^2}$。$x = \pm1$ で 0（極大・極小）。|$\left(\tfrac{x}{x^2 + 1}\right)' = \tfrac{1 - x^2}{(x^2 + 1)^2}$，在 $x = \pm1$ 处为 0（极大、极小）。`,
      a: [F(R`\frac{1\cdot(x^2 + 1) - x\cdot 2x}{(x^2 + 1)^2}`), Y(R`= \frac{1 - x^2}{(x^2 + 1)^2}`)] },
    { a: [F(R`f(x) = \frac{2x + 1}{x - 3}`, { c: 'b' })],
      ex: { k: 'der', q: R`f(x) = \frac{2x + 1}{x - 3}`, f: '(2x+1)/(x-3)', sol: [R`\frac{2(x - 3) - (2x + 1)\cdot 1}{(x - 3)^2}`, R`f'(x) = -\frac{7}{(x - 3)^2}`] } });

  card('Rules/Chain rule', 'Chain rule|Dérivation en chaîne|Regla de la cadena|合成関数の微分|链式法则',
    { s: R`A function of a function: rates multiply. If $y$ changes 3 times as fast as $u$, and $u$ twice as fast as $x$, then $y$ changes 6 times as fast as $x$. Work from the outside in, multiplying one derivative per layer.|Une fonction de fonction : les taux se multiplient. Si $y$ varie 3 fois plus vite que $u$, et $u$ 2 fois plus vite que $x$, alors $y$ varie 6 fois plus vite que $x$. On travaille de l’extérieur vers l’intérieur, une dérivée par couche.|Una función de función: las tasas se multiplican. Si $y$ cambia 3 veces más rápido que $u$ y $u$ el doble que $x$, entonces $y$ cambia 6 veces más rápido que $x$. Trabaja de fuera hacia dentro, una derivada por capa.|関数の関数では変化率が掛け算になる。$y$ が $u$ の 3 倍、$u$ が $x$ の 2 倍の速さで変われば、$y$ は $x$ の 6 倍。外側から内側へ、層ごとに微分を掛ける。|复合函数：变化率相乘。若 $y$ 的变化速度是 $u$ 的 3 倍，$u$ 是 $x$ 的 2 倍，则 $y$ 是 $x$ 的 6 倍。由外向内，每层乘一个导数。`,
      a: [Y(R`\big(f(g(x))\big)' = f'(g(x))\cdot g'(x)`), F(R`\frac{dy}{dx} = \frac{dy}{du}\cdot\frac{du}{dx}`), AX([-3, 3], [-1.5, 3.5]), P('sqrt(1+x^2)'), P('x/sqrt(1+x^2)', 'b', { d: 400 })] },
    { s: R`$\left(\sqrt{1 + x^2}\right)'$: outside $\sqrt{u}$, derivative $\tfrac{1}{2\sqrt u}$; inside $u = 1 + x^2$, derivative $2x$. Product: $\tfrac{x}{\sqrt{1 + x^2}}$.|$\left(\sqrt{1 + x^2}\right)'$ : extérieur $\sqrt{u}$, dérivée $\tfrac{1}{2\sqrt u}$ ; intérieur $u = 1 + x^2$, dérivée $2x$. Produit : $\tfrac{x}{\sqrt{1 + x^2}}$.|$\left(\sqrt{1 + x^2}\right)'$: exterior $\sqrt{u}$, derivada $\tfrac{1}{2\sqrt u}$; interior $u = 1 + x^2$, derivada $2x$. Producto: $\tfrac{x}{\sqrt{1 + x^2}}$.|$\left(\sqrt{1 + x^2}\right)' = \tfrac{1}{2\sqrt{1 + x^2}}\cdot 2x = \tfrac{x}{\sqrt{1 + x^2}}$。|$\left(\sqrt{1 + x^2}\right)' = \tfrac{1}{2\sqrt{1 + x^2}}\cdot 2x = \tfrac{x}{\sqrt{1 + x^2}}$。`,
      a: [F(R`\frac{1}{2\sqrt{1 + x^2}}\cdot 2x`), Y(R`= \frac{x}{\sqrt{1 + x^2}}`)] },
    { a: [F(R`f(x) = e^{\sin x}`, { c: 'b' })],
      ex: { k: 'der', q: R`f(x) = e^{\sin x}`, f: 'e^(sin(x))', sol: [R`\text{outside } e^u,\ \text{inside } u = \sin x`, R`f'(x) = e^{\sin x}\cos x`] } });

  card('Rules/Inverse function', 'Derivative of an inverse function|Dérivée de la réciproque|Derivada de la función inversa|逆関数の微分|反函数的导数',
    { s: R`The graph of $f^{-1}$ is the mirror image of the graph of $f$ in $y = x$, and a mirror turns a slope $m$ into $\tfrac1m$. So the slope of $f^{-1}$ at $y = f(x)$ is $\tfrac{1}{f'(x)}$ — you never need a formula for $f^{-1}$.|Le graphe de $f^{-1}$ est le symétrique de celui de $f$ par rapport à $y = x$, et ce miroir change une pente $m$ en $\tfrac1m$. La pente de $f^{-1}$ en $y = f(x)$ vaut donc $\tfrac{1}{f'(x)}$ — sans jamais connaître $f^{-1}$.|La gráfica de $f^{-1}$ es la de $f$ reflejada en $y = x$, y ese espejo convierte una pendiente $m$ en $\tfrac1m$. Así la pendiente de $f^{-1}$ en $y = f(x)$ es $\tfrac{1}{f'(x)}$, sin necesitar la fórmula de $f^{-1}$.|$f^{-1}$ のグラフは $f$ を $y = x$ で折り返したもので、傾き $m$ は $\tfrac1m$ になる。$y = f(x)$ での $f^{-1}$ の傾きは $\tfrac{1}{f'(x)}$（$f^{-1}$ の式は不要）。|$f^{-1}$ 的图像是 $f$ 关于 $y = x$ 的镜像，镜像把斜率 $m$ 变成 $\tfrac1m$。所以 $f^{-1}$ 在 $y = f(x)$ 处的斜率为 $\tfrac{1}{f'(x)}$——根本不需要 $f^{-1}$ 的表达式。`,
      a: [Y(R`(f^{-1})'(y) = \frac{1}{f'(x)},\quad y = f(x)`), AX([-0.5, 4], [-0.5, 4]), P('x^3/8+x/2'), P('x', 'g', { dash: true }), PT(2, 2, '')] },
    { s: R`$f(x) = x^3 + x$: $f(1) = 2$ and $f'(1) = 4$, so $(f^{-1})'(2) = \tfrac14$ — although solving $x^3 + x = y$ for $x$ would be hard.|$f(x) = x^3 + x$ : $f(1) = 2$ et $f'(1) = 4$, donc $(f^{-1})'(2) = \tfrac14$ — alors que résoudre $x^3 + x = y$ serait difficile.|$f(x) = x^3 + x$: $f(1) = 2$ y $f'(1) = 4$, así que $(f^{-1})'(2) = \tfrac14$, aunque despejar $x$ en $x^3 + x = y$ sería difícil.|$f(x) = x^3 + x$：$f(1) = 2$、$f'(1) = 4$ より $(f^{-1})'(2) = \tfrac14$。|$f(x) = x^3 + x$：$f(1) = 2$，$f'(1) = 4$，所以 $(f^{-1})'(2) = \tfrac14$。`,
      a: [F(R`f(1) = 2,\quad f'(1) = 3 + 1 = 4`), Y(R`(f^{-1})'(2) = \frac14`)] },
    { a: [F(R`f(x) = x^5 + 2x + 1`, { c: 'b' })],
      ex: { k: 'val', v: '1/7', q: R`For $f(x) = x^5 + 2x + 1$, find $(f^{-1})'(4)$.|Pour $f(x) = x^5 + 2x + 1$, calculez $(f^{-1})'(4)$.|Para $f(x) = x^5 + 2x + 1$, halla $(f^{-1})'(4)$.|$f(x) = x^5 + 2x + 1$ について $(f^{-1})'(4)$ を求めよ。|对 $f(x) = x^5 + 2x + 1$，求 $(f^{-1})'(4)$。`,
        sol: [R`f(1) = 4`, R`f'(x) = 5x^4 + 2,\ f'(1) = 7`, R`(f^{-1})'(4) = \frac17`] } });

  card('Implicit, parametric, related rates/Implicit differentiation', 'Implicit differentiation|Dérivation implicite|Derivación implícita|陰関数の微分|隐函数求导',
    { s: R`When $y$ is tied to $x$ by an equation you cannot solve, differentiate both sides anyway, treating $y$ as a function of $x$: every time $y$ is differentiated, a factor $y'$ appears. Then solve for $y'$.|Quand $y$ est lié à $x$ par une équation qu’on ne sait pas résoudre, on dérive quand même les deux membres en voyant $y$ comme une fonction de $x$ : à chaque dérivation de $y$ apparaît un facteur $y'$. Puis on isole $y'$.|Cuando $y$ está ligada a $x$ por una ecuación que no se puede despejar, deriva igualmente los dos miembros tratando $y$ como función de $x$: cada vez que derivas $y$ aparece un factor $y'$. Luego despeja $y'$.|$y$ が解けない方程式で $x$ と結ばれていても、$y$ を $x$ の関数とみて両辺を微分する。$y$ を微分するたびに $y'$ が掛かる。最後に $y'$ について解く。|当 $y$ 与 $x$ 由解不出的方程联系时，照样两边求导，把 $y$看作 $x$ 的函数：每次对 $y$ 求导都出现因子 $y'$。最后解出 $y'$。`,
      a: [F(R`\frac{d}{dx}y^2 = 2y\,y'`), Y(R`F(x, y) = 0 \Rightarrow y' = -\frac{F_x}{F_y}`), ['ax', { xw: [-6, 6], yw: [-6, 6], eq: true }], ['p', 'x^2+y^2=25', { c: 'y' }], P('4-0.75(x-3)', 'b'), PT(3, 4, '(3, 4)')] },
    { s: R`Circle $x^2 + y^2 = 25$: $2x + 2y\,y' = 0$, so $y' = -\tfrac xy$. At $(3, 4)$ the slope is $-\tfrac34$ — perpendicular to the radius, as it should be.|Cercle $x^2 + y^2 = 25$ : $2x + 2y\,y' = 0$, donc $y' = -\tfrac xy$. En $(3, 4)$ la pente vaut $-\tfrac34$ — perpendiculaire au rayon, comme il se doit.|Circunferencia $x^2 + y^2 = 25$: $2x + 2y\,y' = 0$, así que $y' = -\tfrac xy$. En $(3, 4)$ la pendiente es $-\tfrac34$: perpendicular al radio, como debe ser.|円 $x^2 + y^2 = 25$：$2x + 2y\,y' = 0$ より $y' = -\tfrac xy$。$(3, 4)$ で $-\tfrac34$（半径に垂直）。|圆 $x^2 + y^2 = 25$：$2x + 2y\,y' = 0$，$y' = -\tfrac xy$。在 $(3, 4)$ 处斜率 $-\tfrac34$——与半径垂直。`,
      a: [F(R`2x + 2y\,y' = 0`), Y(R`y' = -\frac xy = -\frac34\ \text{at}\ (3, 4)`)] },
    { a: [F(R`x^3 + y^3 = 9,\quad (1, 2)`, { c: 'b' })],
      ex: { k: 'val', v: '-1/4', q: R`Find $y'$ at $(1, 2)$ on the curve $x^3 + y^3 = 9$.|Calculez $y'$ au point $(1, 2)$ de la courbe $x^3 + y^3 = 9$.|Halla $y'$ en $(1, 2)$ sobre la curva $x^3 + y^3 = 9$.|曲線 $x^3 + y^3 = 9$ 上の点 $(1, 2)$ で $y'$ を求めよ。|求曲线 $x^3 + y^3 = 9$ 在 $(1, 2)$ 处的 $y'$。`,
        sol: [R`3x^2 + 3y^2y' = 0`, R`y' = -\frac{x^2}{y^2} = -\frac14`] } });

  card('Implicit, parametric, related rates/Parametric curves', 'Parametric curves|Courbes paramétrées|Curvas paramétricas|媒介変数表示の曲線|参数曲线',
    { s: R`When both $x$ and $y$ depend on a time $t$, the slope of the path is how fast $y$ moves divided by how fast $x$ moves. No need to eliminate $t$.|Quand $x$ et $y$ dépendent tous deux d’un temps $t$, la pente de la trajectoire est la vitesse de $y$ divisée par celle de $x$. Inutile d’éliminer $t$.|Cuando $x$ e $y$ dependen de un tiempo $t$, la pendiente de la trayectoria es lo rápido que se mueve $y$ dividido entre lo rápido que se mueve $x$. No hace falta eliminar $t$.|$x$ と $y$ がともに時間 $t$ に依存するとき、軌跡の傾きは $y$ の速さ ÷ $x$ の速さ。$t$ を消去する必要はない。|当 $x$、$y$ 都依赖时间 $t$ 时，轨迹斜率等于 $y$ 的变化速度除以 $x$ 的变化速度。不必消去 $t$。`,
      a: [Y(R`\frac{dy}{dx} = \frac{dy/dt}{dx/dt}`)] },
    { s: R`$x = t^2$, $y = t^3$: $\tfrac{dy}{dx} = \tfrac{3t^2}{2t} = \tfrac{3t}2$. At $t = 2$ (the point $(4, 8)$) the slope is 3.|$x = t^2$, $y = t^3$ : $\tfrac{dy}{dx} = \tfrac{3t^2}{2t} = \tfrac{3t}2$. En $t = 2$ (le point $(4, 8)$) la pente vaut 3.|$x = t^2$, $y = t^3$: $\tfrac{dy}{dx} = \tfrac{3t^2}{2t} = \tfrac{3t}2$. En $t = 2$ (el punto $(4, 8)$) la pendiente es 3.|$x = t^2$, $y = t^3$：$\tfrac{dy}{dx} = \tfrac{3t}2$。$t = 2$（点 $(4, 8)$）で 3。|$x = t^2$，$y = t^3$：$\tfrac{dy}{dx} = \tfrac{3t}2$，$t = 2$（点 $(4, 8)$）时为 3。`,
      a: [F(R`\frac{dy}{dx} = \frac{3t^2}{2t} = \frac{3t}{2}`), Y(R`t = 2:\ \frac{dy}{dx} = 3`), AX([-0.5, 6], [-1, 12]), P('x^1.5'), PT(4, 8, '(4, 8)')] },
    { a: [F(R`x = \cos t,\ y = \sin t,\quad t = \tfrac\pi3`, { c: 'b' })],
      ex: { k: 'val', v: '-1/sqrt(3)', q: R`For $x = \cos t$, $y = \sin t$, find $\frac{dy}{dx}$ at $t = \frac\pi3$.|Pour $x = \cos t$, $y = \sin t$, calculez $\frac{dy}{dx}$ en $t = \frac\pi3$.|Para $x = \cos t$, $y = \sin t$, halla $\frac{dy}{dx}$ en $t = \frac\pi3$.|$x = \cos t$, $y = \sin t$ のとき $t = \frac\pi3$ での $\frac{dy}{dx}$ を求めよ。|对 $x = \cos t$，$y = \sin t$，求 $t = \frac\pi3$ 时的 $\frac{dy}{dx}$。`,
        sol: [R`\frac{dy}{dx} = \frac{\cos t}{-\sin t} = -\cot t`, R`-\cot\frac\pi3 = -\frac{1}{\sqrt3}`] } });

  card('Implicit, parametric, related rates/Related rates', 'Related rates|Vitesses liées|Razones de cambio relacionadas|関連する変化率|相关变化率',
    { s: R`Two quantities linked by a formula change at linked speeds. Write the formula, differentiate with respect to time $t$ (chain rule), and plug in the numbers at the moment asked — only after differentiating.|Deux grandeurs liées par une formule varient à des vitesses liées. On écrit la formule, on dérive par rapport au temps $t$ (dérivation en chaîne), puis on remplace par les valeurs à l’instant demandé — seulement après avoir dérivé.|Dos magnitudes unidas por una fórmula cambian con velocidades relacionadas. Escribe la fórmula, deriva respecto al tiempo $t$ (regla de la cadena) y sustituye los números del instante pedido, solo después de derivar.|式で結ばれた 2 つの量は、結びついた速さで変わる。式を書き、時間 $t$ で微分（合成関数）し、指定の瞬間の値は微分の後で代入。|由公式联系的两个量以相关的速度变化。写出公式，对时间 $t$ 求导（链式法则），求导之后再代入所问时刻的数值。`,
      a: [Y(R`\frac{dA}{dt} = \frac{dA}{dr}\cdot\frac{dr}{dt}`), F(R`A = \pi r^2 \Rightarrow \frac{dA}{dt} = 2\pi r\frac{dr}{dt}`)] },
    { s: R`A ripple’s radius grows at 2 cm/s. When $r = 5$ cm, the area grows at $2\pi\cdot 5\cdot 2 = 20\pi \approx 62.8$ cm²/s.|Le rayon d’une onde croît de 2 cm/s. Quand $r = 5$ cm, l’aire croît de $2\pi\cdot 5\cdot 2 = 20\pi \approx 62{,}8$ cm²/s.|El radio de una onda crece 2 cm/s. Cuando $r = 5$ cm, el área crece $2\pi\cdot 5\cdot 2 = 20\pi \approx 62{,}8$ cm²/s.|波紋の半径が毎秒 2 cm 増える。$r = 5$ のとき面積は毎秒 $20\pi \approx 62.8$ cm² 増える。|水波半径每秒增加 2 cm。$r = 5$ cm 时，面积增长率为 $20\pi \approx 62.8$ cm²/s。`,
      a: [F(R`\frac{dA}{dt} = 2\pi r\,\frac{dr}{dt}`), Y(R`= 2\pi\cdot 5\cdot 2 = 20\pi`)] },
    { a: [F(R`V = \tfrac43\pi r^3,\quad \frac{dr}{dt} = 0.1,\ r = 3`, { c: 'b' })],
      ex: { k: 'val', v: '3.6pi', q: R`A balloon’s radius grows at $0.1$ cm/s. How fast is its volume growing when $r = 3$ cm?|Le rayon d’un ballon croît de $0{,}1$ cm/s. À quelle vitesse croît son volume quand $r = 3$ cm ?|El radio de un globo crece $0{,}1$ cm/s. ¿A qué ritmo crece su volumen cuando $r = 3$ cm?|風船の半径が毎秒 $0.1$ cm 増える。$r = 3$ cm のとき体積の増加率を求めよ。|气球半径每秒增加 $0.1$ cm。$r = 3$ cm 时体积增长多快？`,
        sol: [R`\frac{dV}{dt} = 4\pi r^2\frac{dr}{dt}`, R`= 4\pi\cdot 9\cdot 0.1 = 3.6\pi \approx 11.3`] } });

  card('Implicit, parametric, related rates/Logarithmic differentiation', 'Logarithmic differentiation|Dérivation logarithmique|Derivación logarítmica|対数微分法|对数求导法',
    { s: R`Take $\ln$ of both sides first: powers come down, products become sums, quotients differences. Differentiate ($\tfrac{y'}{y}$ on the left) and multiply by $y$. Essential when $x$ is in the exponent and the base.|On prend d’abord le $\ln$ des deux membres : les puissances descendent, les produits deviennent des sommes. On dérive ($\tfrac{y'}{y}$ à gauche) et on multiplie par $y$. Indispensable quand $x$ est à la fois dans la base et l’exposant.|Toma primero $\ln$ en los dos miembros: las potencias bajan, los productos pasan a sumas. Deriva ($\tfrac{y'}{y}$ a la izquierda) y multiplica por $y$. Imprescindible cuando $x$ está en la base y en el exponente.|まず両辺の対数をとる：累乗は前に下り、積は和に。微分して（左辺は $\tfrac{y'}{y}$）$y$ を掛ける。底にも指数にも $x$ があるとき必須。|先两边取 $\ln$：幂下来，积变和。求导（左边为 $\tfrac{y'}{y}$），再乘以 $y$。底和指数都含 $x$ 时必不可少。`,
      a: [Y(R`(\ln y)' = \frac{y'}{y} \Rightarrow y' = y\,(\ln y)'`)] },
    { s: R`$y = x^x$: $\ln y = x\ln x$, so $\tfrac{y'}{y} = \ln x + 1$ and $y' = x^x(\ln x + 1)$.|$y = x^x$ : $\ln y = x\ln x$, donc $\tfrac{y'}{y} = \ln x + 1$ et $y' = x^x(\ln x + 1)$.|$y = x^x$: $\ln y = x\ln x$, así que $\tfrac{y'}{y} = \ln x + 1$ e $y' = x^x(\ln x + 1)$.|$y = x^x$：$\ln y = x\ln x$、$\tfrac{y'}{y} = \ln x + 1$、$y' = x^x(\ln x + 1)$。|$y = x^x$：$\ln y = x\ln x$，$\tfrac{y'}{y} = \ln x + 1$，$y' = x^x(\ln x + 1)$。`,
      a: [F(R`\ln y = x\ln x`), F(R`\frac{y'}{y} = \ln x + 1`), Y(R`y' = x^x(\ln x + 1)`)] },
    { a: [F(R`f(x) = x^{\ln x}`, { c: 'b' })],
      ex: { k: 'der', q: R`f(x) = x^{\ln x}\quad (x > 0)`, f: 'x^(ln(x))', sol: [R`\ln y = (\ln x)^2`, R`\frac{y'}{y} = \frac{2\ln x}{x}`, R`f'(x) = x^{\ln x}\cdot\frac{2\ln x}{x}`] } });

  card('Shape of a graph/Monotonicity', 'Increasing and decreasing|Sens de variation|Crecimiento y decrecimiento|増加・減少|单调性',
    { s: R`The sign of $f'$ tells the direction: positive slope, the graph goes up; negative, it goes down. Find where $f' = 0$, then test the sign of $f'$ between those points (a sign table).|Le signe de $f'$ donne le sens : pente positive, la courbe monte ; négative, elle descend. On cherche où $f' = 0$, puis on étudie le signe de $f'$ entre ces points (tableau de signes).|El signo de $f'$ da el sentido: pendiente positiva, la gráfica sube; negativa, baja. Busca dónde $f' = 0$ y estudia el signo de $f'$ entre esos puntos (tabla de signos).|$f'$ の符号が向きを決める：正なら増加、負なら減少。$f' = 0$ となる点を求め、その間で $f'$ の符号を調べる（増減表）。|$f'$ 的符号决定方向：正则上升，负则下降。求 $f' = 0$ 的点，再判断各段 $f'$ 的符号（符号表）。`,
      a: [Y(R`f' > 0 \Rightarrow f \nearrow,\quad f' < 0 \Rightarrow f \searrow`), AX([-2.5, 2.5], [-4, 4]), P('x^3-3x'), P('3x^2-3', 'b', { d: 400 })] },
    { s: R`$f(x) = x^3 - 3x$: $f'(x) = 3(x - 1)(x + 1)$ is positive for $x < -1$ and $x > 1$, negative in between. So $f$ rises, falls on $(-1, 1)$, then rises again.|$f(x) = x^3 - 3x$ : $f'(x) = 3(x - 1)(x + 1)$ est positive pour $x < -1$ et $x > 1$, négative entre les deux. $f$ monte, descend sur $]-1, 1[$, puis remonte.|$f(x) = x^3 - 3x$: $f'(x) = 3(x - 1)(x + 1)$ es positiva para $x < -1$ y $x > 1$ y negativa entre medias. $f$ sube, baja en $(-1, 1)$ y vuelve a subir.|$f(x) = x^3 - 3x$：$f'(x) = 3(x - 1)(x + 1)$。$(-1, 1)$ で減少、その外で増加。|$f(x) = x^3 - 3x$：$f'(x) = 3(x - 1)(x + 1)$，在 $(-1, 1)$ 上递减，其余递增。`,
      a: [F(R`f'(x) = 3(x - 1)(x + 1)`), Y(R`\searrow\ \text{on}\ (-1, 1),\quad \nearrow\ \text{elsewhere}`)] },
    { a: [F(R`f(x) = x^3 - 12x`, { c: 'b' }), AX([-4.5, 4.5], [-20, 20]), P('x^3-12x')],
      ex: { k: 'roots', v: [-2, 2], q: R`$f(x) = x^3 - 12x$ decreases exactly on an interval $(a, b)$. Give $a$ and $b$.|$f(x) = x^3 - 12x$ décroît exactement sur un intervalle $]a, b[$. Donnez $a$ et $b$.|$f(x) = x^3 - 12x$ decrece exactamente en un intervalo $(a, b)$. Da $a$ y $b$.|$f(x) = x^3 - 12x$ が減少する区間 $(a, b)$ の $a$, $b$ を答えよ。|$f(x) = x^3 - 12x$ 恰在区间 $(a, b)$ 上递减，写出 $a$、$b$。`,
        sol: [R`f'(x) = 3x^2 - 12 = 3(x - 2)(x + 2)`, R`f' < 0 \iff -2 < x < 2`] } });

  card('Shape of a graph/Critical points', 'Critical points|Points critiques|Puntos críticos|臨界点|临界点',
    { s: R`Maxima and minima can only happen where the tangent is horizontal ($f' = 0$) or where there is no derivative (a corner like $\lvert x\rvert$ at 0). These are the critical points: the only candidates to check.|Maxima et minima ne peuvent se trouver que là où la tangente est horizontale ($f' = 0$) ou là où il n’y a pas de dérivée (un angle comme $\lvert x\rvert$ en 0). Ce sont les points critiques : les seuls candidats.|Máximos y mínimos solo pueden estar donde la tangente es horizontal ($f' = 0$) o donde no hay derivada (un pico como $\lvert x\rvert$ en 0). Son los puntos críticos: los únicos candidatos.|極大・極小は接線が水平（$f' = 0$）か微分できない所（$\lvert x\rvert$ の 0 のような角）にしか起こらない。これが臨界点で、調べる候補はこれだけ。|极值只能出现在切线水平（$f' = 0$）或不可导处（如 $\lvert x\rvert$ 在 0 处的尖点）。这些就是临界点：唯一需要检查的候选点。`,
      a: [Y(R`f'(c) = 0\ \text{or}\ f'(c)\ \text{does not exist}`), AX([-1, 4.5], [-1, 6]), P('x^3-6x^2+9x'), PT(1, 4, 'x = 1'), PT(3, 0, 'x = 3')] },
    { s: R`$f(x) = x^3 - 6x^2 + 9x$: $f'(x) = 3x^2 - 12x + 9 = 3(x - 1)(x - 3)$, so the critical points are $x = 1$ and $x = 3$.|$f(x) = x^3 - 6x^2 + 9x$ : $f'(x) = 3(x - 1)(x - 3)$, points critiques $x = 1$ et $x = 3$.|$f(x) = x^3 - 6x^2 + 9x$: $f'(x) = 3(x - 1)(x - 3)$, puntos críticos $x = 1$ y $x = 3$.|$f(x) = x^3 - 6x^2 + 9x$：$f'(x) = 3(x - 1)(x - 3)$、臨界点 $x = 1, 3$。|$f(x) = x^3 - 6x^2 + 9x$：$f'(x) = 3(x - 1)(x - 3)$，临界点 $x = 1, 3$。`,
      a: [F(R`f'(x) = 3x^2 - 12x + 9`), Y(R`= 3(x - 1)(x - 3) = 0 \Rightarrow x = 1,\ 3`)] },
    { a: [F(R`f(x) = x^4 - 8x^2`, { c: 'b' }), AX([-3.5, 3.5], [-20, 15]), P('x^4-8x^2')],
      ex: { k: 'roots', v: [0, 2, -2], q: R`Find all critical points of $f(x) = x^4 - 8x^2$.|Trouvez tous les points critiques de $f(x) = x^4 - 8x^2$.|Halla todos los puntos críticos de $f(x) = x^4 - 8x^2$.|$f(x) = x^4 - 8x^2$ の臨界点をすべて求めよ。|求 $f(x) = x^4 - 8x^2$ 的所有临界点。`,
        sol: [R`f'(x) = 4x^3 - 16x = 4x(x^2 - 4)`, R`x = 0,\ x = 2,\ x = -2`] } });

  card('Shape of a graph/Second derivative test', 'Second derivative test|Test de la dérivée seconde|Criterio de la segunda derivada|2 階微分による判定|二阶导数判别法',
    { s: R`At a critical point the curve is flat; the second derivative says which way it bends. Bending up ($f'' > 0$, a cup) means a minimum; bending down ($f'' < 0$, a cap) means a maximum. If $f'' = 0$ the test says nothing.|En un point critique la courbe est horizontale ; la dérivée seconde dit de quel côté elle se courbe. Vers le haut ($f'' > 0$, une coupe) : minimum ; vers le bas ($f'' < 0$, un chapeau) : maximum. Si $f'' = 0$, on ne conclut pas.|En un punto crítico la curva está plana; la segunda derivada dice hacia dónde se dobla. Hacia arriba ($f'' > 0$, una taza): mínimo; hacia abajo ($f'' < 0$, un gorro): máximo. Si $f'' = 0$ no decide.|臨界点では曲線は水平。2 階微分が曲がる向きを教える：上に凸でない（$f'' > 0$、カップ）なら極小、$f'' < 0$（帽子）なら極大。$f'' = 0$ なら判定不能。|在临界点曲线是平的；二阶导数告诉它向哪弯。向上弯（$f'' > 0$，杯形）是极小；向下弯（$f'' < 0$，帽形）是极大。$f'' = 0$ 时无法判断。`,
      a: [Y(R`f'(c) = 0:\ f''(c) < 0 \Rightarrow \max,\ f''(c) > 0 \Rightarrow \min`, { s: 22 }), AX([-2.5, 2.5], [-4, 4]), P('x^3-3x'), PT(-1, 2, 'max'), PT(1, -2, 'min')] },
    { s: R`$f(x) = x^3 - 3x$: $f''(x) = 6x$. At $x = -1$: $f'' = -6 < 0$, maximum $f(-1) = 2$. At $x = 1$: $f'' = 6 > 0$, minimum $f(1) = -2$.|$f(x) = x^3 - 3x$ : $f''(x) = 6x$. En $x = -1$ : $f'' = -6 < 0$, maximum $f(-1) = 2$. En $x = 1$ : $f'' = 6 > 0$, minimum $f(1) = -2$.|$f(x) = x^3 - 3x$: $f''(x) = 6x$. En $x = -1$: $f'' = -6 < 0$, máximo $f(-1) = 2$. En $x = 1$: $f'' = 6 > 0$, mínimo $f(1) = -2$.|$f(x) = x^3 - 3x$：$f''(x) = 6x$。$x = -1$ で極大 2、$x = 1$ で極小 $-2$。|$f(x) = x^3 - 3x$：$f''(x) = 6x$。$x = -1$ 处极大值 2，$x = 1$ 处极小值 $-2$。`,
      a: [F(R`f''(-1) = -6 < 0:\ \max = 2`), Y(R`f''(1) = 6 > 0:\ \min = -2`)] },
    { a: [F(R`f(x) = x^3 - 3x^2 - 9x + 5`, { c: 'b' }), AX([-3, 5], [-25, 15]), P('x^3-3x^2-9x+5')],
      ex: { k: 'val', v: '10', q: R`Find the local maximum value of $f(x) = x^3 - 3x^2 - 9x + 5$.|Trouvez la valeur du maximum local de $f(x) = x^3 - 3x^2 - 9x + 5$.|Halla el valor del máximo local de $f(x) = x^3 - 3x^2 - 9x + 5$.|$f(x) = x^3 - 3x^2 - 9x + 5$ の極大値を求めよ。|求 $f(x) = x^3 - 3x^2 - 9x + 5$ 的极大值。`,
        sol: [R`f'(x) = 3(x - 3)(x + 1)`, R`f''(-1) = -12 < 0\ \Rightarrow\ \max\ \text{at}\ x = -1`, R`f(-1) = -1 - 3 + 9 + 5 = 10`] } });

  card('Shape of a graph/Concavity', 'Concavity|Convexité|Concavidad|凹凸|凹凸性',
    { s: R`$f''$ is the rate of change of the slope. If it is positive the slope keeps increasing and the curve bends up like a cup; if negative, it bends down like a cap. The tangent lies below a cup and above a cap.|$f''$ est la vitesse de variation de la pente. Positive : la pente augmente et la courbe se courbe vers le haut (convexe) ; négative : vers le bas (concave). La tangente est sous une courbe convexe, au-dessus d’une concave.|$f''$ es la variación de la pendiente. Si es positiva la pendiente aumenta y la curva se dobla hacia arriba como una taza; si es negativa, hacia abajo como un gorro. La tangente queda por debajo de la taza y por encima del gorro.|$f''$ は傾きの変化率。正なら傾きが増えカップ形（下に凸）、負なら帽子形（上に凸）。接線はカップの下、帽子の上にある。|$f''$ 是斜率的变化率。为正时斜率不断增大，曲线像杯子一样向上弯；为负时像帽子向下弯。切线在杯形下方、帽形上方。`,
      a: [Y(R`f'' > 0 \Rightarrow \cup,\quad f'' < 0 \Rightarrow \cap`), AX([-2, 2], [-4, 4]), P('x^3'), P('6x', 'b', { d: 400 })] },
    { s: R`$f(x) = x^3$: $f''(x) = 6x$, negative for $x < 0$ (cap) and positive for $x > 0$ (cup). It switches at $x = 0$.|$f(x) = x^3$ : $f''(x) = 6x$, négative pour $x < 0$ (concave) et positive pour $x > 0$ (convexe). Elle change en $x = 0$.|$f(x) = x^3$: $f''(x) = 6x$, negativa para $x < 0$ (gorro) y positiva para $x > 0$ (taza). Cambia en $x = 0$.|$f(x) = x^3$：$f''(x) = 6x$。$x < 0$ で上に凸、$x > 0$ で下に凸。|$f(x) = x^3$：$f''(x) = 6x$，$x < 0$ 时凸（帽形），$x > 0$ 时凹（杯形）。`,
      a: [F(R`f''(x) = 6x`), Y(R`x < 0:\ \cap,\quad x > 0:\ \cup`)] },
    { a: [F(R`f(x) = x^4 - 6x^2`, { c: 'b' }), AX([-3, 3], [-10, 8]), P('x^4-6x^2')],
      ex: { k: 'roots', v: [-1, 1], q: R`$f(x) = x^4 - 6x^2$ is concave down ($\cap$) exactly on $(a, b)$. Give $a$ and $b$.|$f(x) = x^4 - 6x^2$ est concave ($\cap$) exactement sur $]a, b[$. Donnez $a$ et $b$.|$f(x) = x^4 - 6x^2$ es cóncava hacia abajo ($\cap$) exactamente en $(a, b)$. Da $a$ y $b$.|$f(x) = x^4 - 6x^2$ が上に凸（$\cap$）となる区間 $(a, b)$ の $a$, $b$ を答えよ。|$f(x) = x^4 - 6x^2$ 恰在 $(a, b)$ 上向下弯（$\cap$），写出 $a$、$b$。`,
        sol: [R`f''(x) = 12x^2 - 12 = 12(x - 1)(x + 1)`, R`f'' < 0 \iff -1 < x < 1`] } });

  card('Shape of a graph/Inflection point', 'Inflection points|Points d’inflexion|Puntos de inflexión|変曲点|拐点',
    { s: R`An inflection point is where the bending changes direction — cup to cap or back. So $f''$ must change sign there; $f''(c) = 0$ alone is not enough ($x^4$ has $f''(0) = 0$ but no inflection).|Un point d’inflexion est l’endroit où la courbure change de sens. $f''$ doit donc y changer de signe ; $f''(c) = 0$ ne suffit pas ($x^4$ a $f''(0) = 0$ sans inflexion).|Un punto de inflexión es donde la curvatura cambia de sentido. Así $f''$ debe cambiar de signo allí; $f''(c) = 0$ no basta ($x^4$ tiene $f''(0) = 0$ pero no hay inflexión).|変曲点は曲がり方の向きが変わる点。$f''$ がそこで符号を変える必要がある（$f''(c) = 0$ だけでは不十分：$x^4$ は $f''(0) = 0$ だが変曲点でない）。|拐点是弯曲方向改变之处。$f''$ 必须在那里变号；仅 $f''(c) = 0$ 不够（$x^4$ 有 $f''(0) = 0$ 但无拐点）。`,
      a: [Y(R`f''(c) = 0\ \text{and}\ f''\ \text{changes sign}`), AX([-1, 3], [-3, 3]), P('x^3-3x^2+2'), PT(1, 0, '(1, 0)')] },
    { s: R`$f(x) = x^3 - 3x^2 + 2$: $f''(x) = 6x - 6$ changes sign at $x = 1$, so $(1, f(1)) = (1, 0)$ is an inflection point.|$f(x) = x^3 - 3x^2 + 2$ : $f''(x) = 6x - 6$ change de signe en $x = 1$ : $(1, 0)$ est un point d’inflexion.|$f(x) = x^3 - 3x^2 + 2$: $f''(x) = 6x - 6$ cambia de signo en $x = 1$, así que $(1, 0)$ es un punto de inflexión.|$f(x) = x^3 - 3x^2 + 2$：$f'' = 6x - 6$ が $x = 1$ で符号を変え、$(1, 0)$ が変曲点。|$f(x) = x^3 - 3x^2 + 2$：$f'' = 6x - 6$ 在 $x = 1$ 变号，$(1, 0)$ 是拐点。`,
      a: [F(R`f''(x) = 6x - 6 = 0 \Rightarrow x = 1`), Y(R`(1, 0)`)] },
    { a: [F(R`f(x) = x^3 + 3x^2 - 1`, { c: 'b' }), AX([-3.5, 1.5], [-2, 4]), P('x^3+3x^2-1')],
      ex: { k: 'pt', v: [-1, 1], q: R`Find the inflection point of $f(x) = x^3 + 3x^2 - 1$.|Trouvez le point d’inflexion de $f(x) = x^3 + 3x^2 - 1$.|Halla el punto de inflexión de $f(x) = x^3 + 3x^2 - 1$.|$f(x) = x^3 + 3x^2 - 1$ の変曲点を求めよ。|求 $f(x) = x^3 + 3x^2 - 1$ 的拐点。`,
        sol: [R`f''(x) = 6x + 6 = 0 \Rightarrow x = -1`, R`f(-1) = -1 + 3 - 1 = 1`, R`(-1, 1)`] } });

  card('Shape of a graph/Global extrema on [a, b]', 'Global extrema on a closed interval|Extremums sur un intervalle fermé|Extremos absolutos en un intervalo cerrado|閉区間での最大・最小|闭区间上的最值',
    { s: R`On a closed interval the largest and smallest values are either at critical points or at the two ends. Make a short list — endpoints plus critical points inside — evaluate $f$ at each, and pick the biggest and smallest.|Sur un intervalle fermé, les valeurs extrêmes sont atteintes en un point critique ou à une extrémité. On fait la liste — extrémités et points critiques intérieurs —, on calcule $f$ en chacun et on prend le plus grand et le plus petit.|En un intervalo cerrado los valores máximo y mínimo están en puntos críticos o en los extremos. Haz una lista —extremos y puntos críticos interiores—, evalúa $f$ en cada uno y elige el mayor y el menor.|閉区間での最大・最小は臨界点か端点で起こる。端点と内部の臨界点を並べ、それぞれの $f$ の値を比べる。|闭区间上的最大最小值在临界点或端点取得。列出端点和区间内的临界点，逐个求 $f$，取最大和最小。`,
      a: [Y(R`\max/\min \in \{f(a),\ f(b),\ f(c_i)\}`), AX([-0.3, 2.3], [-2.5, 2.5]), P('x^3-3x'), PT(0, 0, 'f(0)'), PT(1, -2, 'f(1)'), PT(2, 2, 'f(2)')] },
    { s: R`$f(x) = x^3 - 3x$ on $[0, 2]$: the critical point inside is $x = 1$. Values: $f(0) = 0$, $f(1) = -2$, $f(2) = 2$. Maximum 2 (at an endpoint), minimum $-2$.|$f(x) = x^3 - 3x$ sur $[0, 2]$ : point critique intérieur $x = 1$. Valeurs : $f(0) = 0$, $f(1) = -2$, $f(2) = 2$. Maximum 2 (à une extrémité), minimum $-2$.|$f(x) = x^3 - 3x$ en $[0, 2]$: el punto crítico interior es $x = 1$. Valores: $f(0) = 0$, $f(1) = -2$, $f(2) = 2$. Máximo 2 (en un extremo), mínimo $-2$.|$[0, 2]$ で $f(x) = x^3 - 3x$：臨界点 $x = 1$。$f(0) = 0$, $f(1) = -2$, $f(2) = 2$ で最大 2、最小 $-2$。|$f(x) = x^3 - 3x$ 在 $[0, 2]$：临界点 $x = 1$。$f(0) = 0$，$f(1) = -2$，$f(2) = 2$，最大 2，最小 $-2$。`,
      a: [F(R`f(0) = 0,\ f(1) = -2,\ f(2) = 2`), Y(R`\max = 2,\quad \min = -2`)] },
    { a: [F(R`f(x) = x^3 - 3x^2,\quad [-1, 4]`, { c: 'b' }), AX([-1.3, 4.3], [-6, 17]), P('x^3-3x^2')],
      ex: { k: 'val', v: '16', q: R`Find the maximum value of $f(x) = x^3 - 3x^2$ on $[-1, 4]$.|Trouvez la valeur maximale de $f(x) = x^3 - 3x^2$ sur $[-1, 4]$.|Halla el valor máximo de $f(x) = x^3 - 3x^2$ en $[-1, 4]$.|$[-1, 4]$ における $f(x) = x^3 - 3x^2$ の最大値を求めよ。|求 $f(x) = x^3 - 3x^2$ 在 $[-1, 4]$ 上的最大值。`,
        sol: [R`f'(x) = 3x(x - 2) = 0 \Rightarrow x = 0,\ 2`, R`f(-1) = -4,\ f(0) = 0,\ f(2) = -4,\ f(4) = 16`, R`\max = 16`] } });

  card('Theorems/Rolle', 'Rolle’s theorem|Théorème de Rolle|Teorema de Rolle|ロルの定理|罗尔定理',
    { s: R`A smooth curve that starts and ends at the same height must turn around somewhere in between, and there its tangent is horizontal. The theorem guarantees such a $c$; finding it means solving $f'(c) = 0$ inside $(a, b)$.|Une courbe lisse qui part et arrive à la même hauteur doit faire demi-tour quelque part entre les deux, et là sa tangente est horizontale. Le théorème garantit un tel $c$ ; le trouver, c’est résoudre $f'(c) = 0$ dans $]a, b[$.|Una curva suave que empieza y termina a la misma altura debe dar la vuelta en algún punto intermedio, y ahí su tangente es horizontal. El teorema garantiza ese $c$; hallarlo es resolver $f'(c) = 0$ en $(a, b)$.|同じ高さで始まり終わる滑らかな曲線は、途中で向きを変え、そこで接線が水平。定理はその $c$ の存在を保証し、求めるには $(a, b)$ で $f'(c) = 0$ を解く。|起点终点等高的光滑曲线中间必定掉头，那里切线水平。定理保证这样的 $c$ 存在；求它就是在 $(a, b)$ 内解 $f'(c) = 0$。`,
      a: [Y(R`f(a) = f(b) \Rightarrow \exists\,c:\ f'(c) = 0`), AX([-0.5, 4.5], [-5, 2]), P('x^2-4x'), ['ln', 0, 0, 4, 0, { c: 'b' }], ['tan', 2], PT(2, -4, 'c = 2')] },
    { s: R`$f(x) = x^2 - 4x$ on $[0, 4]$: $f(0) = f(4) = 0$, and $f'(c) = 2c - 4 = 0$ gives $c = 2$, the bottom of the parabola.|$f(x) = x^2 - 4x$ sur $[0, 4]$ : $f(0) = f(4) = 0$, et $f'(c) = 2c - 4 = 0$ donne $c = 2$, le bas de la parabole.|$f(x) = x^2 - 4x$ en $[0, 4]$: $f(0) = f(4) = 0$, y $f'(c) = 2c - 4 = 0$ da $c = 2$, el fondo de la parábola.|$[0, 4]$ で $f(x) = x^2 - 4x$：$f(0) = f(4) = 0$、$f'(c) = 2c - 4 = 0$ より $c = 2$。|$f(x) = x^2 - 4x$ 在 $[0, 4]$：$f(0) = f(4) = 0$，$f'(c) = 2c - 4 = 0$，$c = 2$。`,
      a: [F(R`f(0) = f(4) = 0`), Y(R`f'(c) = 2c - 4 = 0 \Rightarrow c = 2`)] },
    { a: [F(R`f(x) = x^3 - x,\quad [0, 1]`, { c: 'b' }), AX([-0.2, 1.2], [-0.5, 0.3]), P('x^3-x')],
      ex: { k: 'val', v: '1/sqrt(3)', q: R`$f(x) = x^3 - x$ has $f(0) = f(1)$. Find the $c \in (0, 1)$ given by Rolle’s theorem.|$f(x) = x^3 - x$ vérifie $f(0) = f(1)$. Trouvez le $c \in ]0, 1[$ donné par le théorème de Rolle.|$f(x) = x^3 - x$ cumple $f(0) = f(1)$. Halla el $c \in (0, 1)$ que da el teorema de Rolle.|$f(x) = x^3 - x$ は $f(0) = f(1)$。ロルの定理の $c \in (0, 1)$ を求めよ。|$f(x) = x^3 - x$ 满足 $f(0) = f(1)$，求罗尔定理给出的 $c \in (0, 1)$。`,
        sol: [R`f'(c) = 3c^2 - 1 = 0`, R`c = \frac{1}{\sqrt3} \approx 0.577`] } });

  card('Theorems/Mean value theorem', 'Mean value theorem|Théorème des accroissements finis|Teorema del valor medio|平均値の定理|拉格朗日中值定理',
    { s: R`Tilt Rolle’s picture: somewhere between $a$ and $b$ the tangent is parallel to the chord. In words: if your average speed on a trip was 80 km/h, at some instant your speedometer read exactly 80.|On incline la figure de Rolle : quelque part entre $a$ et $b$ la tangente est parallèle à la corde. En mots : si votre vitesse moyenne sur un trajet était 80 km/h, à un instant le compteur a affiché exactement 80.|Inclina el dibujo de Rolle: en algún punto entre $a$ y $b$ la tangente es paralela a la cuerda. Con palabras: si tu velocidad media en un viaje fue 80 km/h, en algún instante el velocímetro marcó exactamente 80.|ロルの図を傾けると、$a$ と $b$ の間のどこかで接線が弦に平行。平均時速 80 km なら、ある瞬間に速度計はちょうど 80 を指した。|把罗尔定理的图倾斜：在 $a$ 与 $b$ 之间某处切线与弦平行。通俗地说：若某次行程平均时速 80 km，某一时刻速度表恰好显示 80。`,
      a: [Y(R`\exists\,c:\ f'(c) = \frac{f(b) - f(a)}{b - a}`), AX([0.5, 3.5], [-0.5, 10]), P('x^2'), ['ln', 1, 1, 3, 9, { c: 'b' }], ['tan', 2], PT(2, 4, 'c')] },
    { s: R`$f(x) = x^2$ on $[1, 3]$: the chord has slope $\tfrac{9 - 1}{2} = 4$, and $f'(c) = 2c = 4$ gives $c = 2$.|$f(x) = x^2$ sur $[1, 3]$ : la corde a pour pente $\tfrac{9 - 1}{2} = 4$, et $f'(c) = 2c = 4$ donne $c = 2$.|$f(x) = x^2$ en $[1, 3]$: la cuerda tiene pendiente $\tfrac{9 - 1}{2} = 4$, y $f'(c) = 2c = 4$ da $c = 2$.|$[1, 3]$ で $f(x) = x^2$：弦の傾き 4、$2c = 4$ より $c = 2$。|$f(x) = x^2$ 在 $[1, 3]$：弦斜率 4，$2c = 4$，$c = 2$。`,
      a: [F(R`\frac{f(3) - f(1)}{3 - 1} = 4`), Y(R`2c = 4 \Rightarrow c = 2`)] },
    { a: [F(R`f(x) = \sqrt x,\quad [0, 4]`, { c: 'b' }), AX([-0.3, 4.5], [-0.3, 2.4]), P('sqrt(x)'), ['ln', 0, 0, 4, 2, { c: 'b' }]],
      ex: { k: 'val', v: '1', q: R`Find the $c$ of the mean value theorem for $f(x) = \sqrt x$ on $[0, 4]$.|Trouvez le $c$ des accroissements finis pour $f(x) = \sqrt x$ sur $[0, 4]$.|Halla el $c$ del teorema del valor medio para $f(x) = \sqrt x$ en $[0, 4]$.|$[0, 4]$ における $f(x) = \sqrt x$ の平均値の定理の $c$ を求めよ。|求 $f(x) = \sqrt x$ 在 $[0, 4]$ 上中值定理的 $c$。`,
        sol: [R`\frac{\sqrt4 - 0}{4} = \frac12`, R`\frac{1}{2\sqrt c} = \frac12 \Rightarrow c = 1`] } });

  card('Theorems/Newton’s method', 'Newton’s method|Méthode de Newton|Método de Newton|ニュートン法|牛顿法',
    { s: R`Start with a guess, follow the tangent down to the $x$-axis, and use that crossing as the next guess. Near a simple root the number of correct digits roughly doubles at each step.|On part d’une estimation, on suit la tangente jusqu’à l’axe des $x$, et ce point d’intersection devient la nouvelle estimation. Près d’une racine simple, le nombre de chiffres exacts double environ à chaque étape.|Parte de una estimación, sigue la tangente hasta el eje $x$ y usa ese corte como nueva estimación. Cerca de una raíz simple, el número de cifras correctas casi se duplica en cada paso.|推定値から接線をたどって $x$ 軸との交点を次の推定値にする。単根の近くでは正しい桁数が毎回ほぼ倍に。|从一个猜测出发，沿切线到 $x$ 轴，交点作为下一个猜测。在单根附近，每步正确位数大约翻倍。`,
      a: [Y(R`x_{n+1} = x_n - \frac{f(x_n)}{f'(x_n)}`), AX([0.8, 2.2], [-1.5, 2.5]), P('x^2-2'), ['tan', 2], PT(2, 2, 'x₀'), PT(1.5, 0, 'x₁', 'b')] },
    { s: R`$\sqrt2$ as the root of $x^2 - 2$, starting at $x_0 = 2$: $x_1 = 2 - \tfrac{2}{4} = 1.5$, $x_2 = 1.5 - \tfrac{0.25}{3} = 1.41667$, already 3 correct decimals.|$\sqrt2$ comme racine de $x^2 - 2$, à partir de $x_0 = 2$ : $x_1 = 2 - \tfrac24 = 1{,}5$, $x_2 = 1{,}5 - \tfrac{0{,}25}{3} = 1{,}41667$, déjà 3 décimales exactes.|$\sqrt2$ como raíz de $x^2 - 2$, desde $x_0 = 2$: $x_1 = 2 - \tfrac24 = 1{,}5$, $x_2 = 1{,}5 - \tfrac{0{,}25}{3} = 1{,}41667$, ya con 3 decimales correctos.|$x^2 - 2$ の根 $\sqrt2$、$x_0 = 2$ から：$x_1 = 1.5$、$x_2 = 1.41667$（すでに小数 3 桁正しい）。|$\sqrt2$ 作为 $x^2 - 2$ 的根，$x_0 = 2$：$x_1 = 1.5$，$x_2 = 1.41667$，已有 3 位正确小数。`,
      a: [F(R`x_1 = 2 - \frac{2}{4} = 1.5`), Y(R`x_2 = 1.5 - \frac{0.25}{3} = 1.41667`)] },
    { a: [F(R`f(x) = x^3 - 2x - 5,\quad x_0 = 2`, { c: 'b' }), AX([1.5, 2.6], [-3, 6]), P('x^3-2x-5'), PT(2, -1, 'x₀')],
      ex: { k: 'val', v: '2.1', q: R`Do one step of Newton’s method on $f(x) = x^3 - 2x - 5$ from $x_0 = 2$. Give $x_1$.|Faites une étape de la méthode de Newton sur $f(x) = x^3 - 2x - 5$ à partir de $x_0 = 2$. Donnez $x_1$.|Haz un paso del método de Newton con $f(x) = x^3 - 2x - 5$ desde $x_0 = 2$. Da $x_1$.|$f(x) = x^3 - 2x - 5$、$x_0 = 2$ からニュートン法を 1 回行い $x_1$ を答えよ。|对 $f(x) = x^3 - 2x - 5$ 从 $x_0 = 2$ 做一步牛顿法，求 $x_1$。`,
        sol: [R`f(2) = -1,\quad f'(2) = 3\cdot 4 - 2 = 10`, R`x_1 = 2 - \frac{-1}{10} = 2.1`] } });

  card('Optimisation/Method', 'Optimisation method|Méthode d’optimisation|Método de optimización|最適化の手順|最优化方法',
    { s: R`1) Write the quantity to optimise. 2) Use the constraint to leave only one variable. 3) Set the derivative to 0. 4) Check it is a max or min (second derivative, or the endpoints). 5) Answer the question that was asked.|1) Écrire la grandeur à optimiser. 2) Utiliser la contrainte pour ne garder qu’une variable. 3) Annuler la dérivée. 4) Vérifier qu’il s’agit d’un max ou d’un min. 5) Répondre à la question posée.|1) Escribe la magnitud a optimizar. 2) Usa la restricción para dejar una sola variable. 3) Iguala la derivada a 0. 4) Comprueba que es máximo o mínimo. 5) Responde a lo que se pregunta.|1) 最適化する量を書く。2) 条件で 1 変数にする。3) 微分を 0 に。4) 最大・最小か確認。5) 問われたことに答える。|1) 写出要优化的量。2) 用约束条件化为一个变量。3) 令导数为 0。4) 检验是最大还是最小。5) 回答所问的问题。`,
      a: [F(R`f(x)\ \to\ f'(x) = 0\ \to\ f''(x)`), W('one variable, derivative = 0, check, answer|une variable, dérivée nulle, vérifier, répondre|una variable, derivada 0, comprobar, responder|1 変数、微分 = 0、確認、解答|一个变量，导数为 0，检验，作答'), AX([-0.5, 20.5], [-10, 110]), P('x*(20-x)'), PT(10, 100, 'x = 10')] },
    { s: R`A rectangle with 40 m of fence: sides $x$ and $20 - x$, area $A = x(20 - x)$. $A' = 20 - 2x = 0$ gives $x = 10$, and $A'' = -2 < 0$: maximum. The best rectangle is a $10\times 10$ square, area 100 m².|Un rectangle entouré de 40 m de clôture : côtés $x$ et $20 - x$, aire $A = x(20 - x)$. $A' = 20 - 2x = 0$ donne $x = 10$, et $A'' = -2 < 0$ : maximum. Le meilleur rectangle est un carré $10\times 10$, d’aire 100 m².|Un rectángulo con 40 m de valla: lados $x$ y $20 - x$, área $A = x(20 - x)$. $A' = 20 - 2x = 0$ da $x = 10$ y $A'' = -2 < 0$: máximo. El mejor es un cuadrado $10\times 10$, de 100 m².|柵 40 m の長方形：辺 $x$, $20 - x$、面積 $A = x(20 - x)$。$A' = 0$ で $x = 10$、$A'' < 0$ で最大。10 × 10 の正方形、面積 100。|40 m 篱笆围矩形：边 $x$、$20 - x$，面积 $A = x(20 - x)$。$A' = 0$ 得 $x = 10$，$A'' < 0$ 为最大。$10\times 10$ 正方形，面积 100。`,
      a: [F(R`A = x(20 - x),\quad A' = 20 - 2x = 0`), Y(R`x = 10,\quad A_{\max} = 100`)] },
    { a: [F(R`V = x(12 - 2x)^2`, { c: 'b' }), AX([-0.3, 6.3], [-10, 140]), P('x*(12-2x)^2')],
      ex: { k: 'val', v: '128', q: R`An open box is made from a $12\times 12$ sheet by cutting squares of side $x$ from the corners. Find the largest possible volume.|On fabrique une boîte sans couvercle à partir d’une feuille $12\times 12$ en découpant des carrés de côté $x$ aux coins. Quel est le volume maximal ?|Se hace una caja abierta con una lámina de $12\times 12$ cortando cuadrados de lado $x$ en las esquinas. Halla el volumen máximo.|$12\times 12$ の板の四隅から一辺 $x$ の正方形を切り取ってふたのない箱を作る。体積の最大値を求めよ。|用 $12\times 12$ 的纸板在四角剪去边长为 $x$ 的正方形做无盖盒子，求最大体积。`,
        sol: [R`V = x(12 - 2x)^2,\ \ V' = (12 - 2x)(12 - 6x)`, R`V' = 0,\ 0 < x < 6 \Rightarrow x = 2`, R`V = 2\cdot 8^2 = 128`] } });

  card('Optimisation/AM–GM shortcut', 'The AM–GM shortcut|L’inégalité arithmético-géométrique|La desigualdad de las medias|相加相乗平均|均值不等式',
    { s: R`For $x > 0$, $x + \tfrac kx$ is smallest when the two terms are equal: $x = \tfrac kx$, i.e. $x = \sqrt k$, and the minimum is $2\sqrt k$. It solves many optimisation problems without derivatives.|Pour $x > 0$, $x + \tfrac kx$ est minimal quand les deux termes sont égaux : $x = \tfrac kx$, soit $x = \sqrt k$, et le minimum vaut $2\sqrt k$. Cela résout bien des problèmes d’optimisation sans dériver.|Para $x > 0$, $x + \tfrac kx$ es mínimo cuando los dos términos son iguales: $x = \tfrac kx$, o sea $x = \sqrt k$, y el mínimo es $2\sqrt k$. Resuelve muchos problemas de optimización sin derivar.|$x > 0$ で $x + \tfrac kx$ は 2 項が等しいとき最小：$x = \sqrt k$、最小値 $2\sqrt k$。微分なしで多くの最適化問題が解ける。|当 $x > 0$ 时，$x + \tfrac kx$ 在两项相等时最小：$x = \sqrt k$，最小值 $2\sqrt k$。许多最优化问题不用求导就能解。`,
      a: [Y(R`x + \frac kx \ge 2\sqrt k\quad (x > 0)`), AX([-0.3, 8], [-0.5, 10]), P('x+4/x'), PT(2, 4, 'x = 2')] },
    { s: R`$x + \tfrac4x \ge 2\sqrt4 = 4$, with equality at $x = 2$: the graph’s lowest point is $(2, 4)$.|$x + \tfrac4x \ge 2\sqrt4 = 4$, avec égalité en $x = 2$ : le point le plus bas est $(2, 4)$.|$x + \tfrac4x \ge 2\sqrt4 = 4$, con igualdad en $x = 2$: el punto más bajo es $(2, 4)$.|$x + \tfrac4x \ge 4$、等号は $x = 2$。最下点は $(2, 4)$。|$x + \tfrac4x \ge 4$，$x = 2$ 时取等，最低点 $(2, 4)$。`,
      a: [Y(R`x + \frac4x \ge 4,\quad x = 2`)] },
    { a: [F(R`xy = 50,\quad P = 2(x + y)`, { c: 'b' })],
      ex: { k: 'val', v: '20sqrt(2)', q: R`A rectangle has area 50. What is its smallest possible perimeter?|Un rectangle a une aire de 50. Quel est son plus petit périmètre possible ?|Un rectángulo tiene área 50. ¿Cuál es su menor perímetro posible?|面積 50 の長方形の周の長さの最小値を求めよ。|面积为 50 的矩形，周长最小是多少？`,
        sol: [R`P = 2\left(x + \frac{50}{x}\right)`, R`x + \frac{50}{x} \ge 2\sqrt{50} = 10\sqrt2`, R`P_{\min} = 20\sqrt2 \approx 28.28`] } });

  card('Optimisation/Fixed perimeter', 'Fixed perimeter: the square wins|Périmètre fixé : le carré gagne|Perímetro fijo: gana el cuadrado|周の長さ一定：正方形が最大|周长一定：正方形面积最大',
    { s: R`With a fixed perimeter $P$, sides $x$ and $\tfrac P2 - x$ give area $x\left(\tfrac P2 - x\right)$, a downward parabola whose top is at $x = \tfrac P4$: all sides equal, a square.|À périmètre fixé $P$, les côtés $x$ et $\tfrac P2 - x$ donnent l’aire $x\left(\tfrac P2 - x\right)$, une parabole tournée vers le bas de sommet $x = \tfrac P4$ : tous les côtés égaux, un carré.|Con perímetro fijo $P$, los lados $x$ y $\tfrac P2 - x$ dan área $x\left(\tfrac P2 - x\right)$, una parábola hacia abajo con vértice en $x = \tfrac P4$: todos los lados iguales, un cuadrado.|周の長さ $P$ 一定なら、辺 $x$, $\tfrac P2 - x$ で面積 $x\left(\tfrac P2 - x\right)$、頂点は $x = \tfrac P4$：正方形。|周长 $P$ 固定时，边为 $x$、$\tfrac P2 - x$，面积 $x\left(\tfrac P2 - x\right)$ 是开口向下的抛物线，顶点 $x = \tfrac P4$：四边相等，正方形。`,
      a: [Y(R`P = 4s \Rightarrow S_{\max} = s^2 = \frac{P^2}{16}`), AX([-0.5, 10.5], [-3, 30]), P('x*(10-x)'), PT(5, 25, 'x = P/4')] },
    { s: R`Perimeter 20: the best rectangle is the $5\times 5$ square, area 25. A $4\times 6$ rectangle only gives 24, a $2\times 8$ only 16.|Périmètre 20 : le meilleur rectangle est le carré $5\times 5$, d’aire 25. Un $4\times 6$ ne donne que 24, un $2\times 8$ que 16.|Perímetro 20: el mejor rectángulo es el cuadrado $5\times 5$, de área 25. Un $4\times 6$ solo da 24 y un $2\times 8$, 16.|周の長さ 20：$5\times 5$ の正方形で面積 25。$4\times 6$ は 24、$2\times 8$ は 16。|周长 20：最佳是 $5\times 5$ 正方形，面积 25；$4\times 6$ 只有 24，$2\times 8$ 只有 16。`,
      a: [F(R`5\times 5 = 25,\quad 4\times 6 = 24,\quad 2\times 8 = 16`), Y(R`S_{\max} = 25`)] },
    { a: [F(R`P = 30`, { c: 'b' })],
      ex: { k: 'val', v: '225/4', q: R`What is the largest area of a rectangle with perimeter 30?|Quelle est l’aire maximale d’un rectangle de périmètre 30 ?|¿Cuál es el área máxima de un rectángulo de perímetro 30?|周の長さ 30 の長方形の面積の最大値を求めよ。|周长为 30 的矩形最大面积是多少？`,
        sol: [R`s = \frac{30}{4} = 7.5`, R`S_{\max} = 7.5^2 = 56.25`] } });

  Cheats.tutor('derivatives', lessons);
})();
